local config = {
  ui_story_5060_50600101_1_dialog_content = "Um concurso de fotografia bem no centro comercial, e o grande prêmio é uma viagem internacional para duas pessoas!",
  ui_story_5060_50600101_2_dialog_content = "Com isso, eu poderia fazer uma escapada romântica com <color=#FFB400>Kobayashi</color>!",
  ui_story_5060_50600101_3_dialog_content = "E qual melhor maneira de ganhar do que tirar fotos da paisagem do nosso mundo natal! Eu realmente sou um gênio, né?",
  ui_story_5060_50600101_4_dialog_content = "Ei, Tohru. Você não disse que íamos voltar para coletar alguns ingredientes exóticos para comida?",
  ui_story_5060_50600101_5_dialog_content = "Por que você ainda está falando sobre isso, Elma? Não se preocupe, podemos reunir todos os ingredientes de que precisamos enquanto tiramos fotos!",
  ui_story_5060_50600101_6_dialog_content = "Bem, não importa. Não temos tempo para discutir isso. Por aqui, pessoal!",
  ui_story_5060_50600101_7_dialog_content = "Ativando o <color=#FFB400>Portal de Teletransporte Mundial</color>—",
  ui_story_5060_50600101_8_dialog_content = "Tudo bem pessoal, preparem-se para finalmente conhecer nossa cidade natal!",
  ui_story_5060_50600101_9_dialog_content = "Hã? Espere...",
  ui_story_5060_50600101_10_dialog_content = "<size=50>Que lugar é esse?!</size>",
  ui_story_5060_50600101_11_dialog_content = "Ativando o Portal de Teletransporte Mundial! Hrrrng—! Vamos lá, ative!",
  ui_story_5060_50600101_12_dialog_content = "Estranho, o portal não liga de jeito nenhum.",
  ui_story_5060_50600101_13_dialog_content = "Ah, isso é ruim... Será que Kanna e Elma também estão presos aqui sem como voltar?",
  ui_story_5060_50600101_14_dialog_content = "Ok, apenas se acalme e observe o ambiente... Algumas coisas neste mundo eu consigo reconhecer.",
  ui_story_5060_50600101_15_dialog_content = "Não é muito diferente do mundo de Kobayashi. Por exemplo, aqui também há lojas de conveniência e transporte público...",
  ui_story_5060_50600101_16_dialog_content = "Bem, vou levar essa boneca mecânica.",
  ui_story_5060_50600101_17_dialog_content = "Seu gosto é impecável, senhora! Sua filha vai adorar este presente fofo e obediente!",
  ui_story_5060_50600101_18_dialog_content = "Por favor, termine rapidamente. Preciso pegar a aeronave para o Shuttle Hub.",
  ui_story_5060_50600101_19_dialog_content = "Considere feito, senhora! Muito obrigado por comprar conosco!",
  ui_story_5060_50600101_20_dialog_content = "Você! Perturbar a ordem das ruas com <color=#FFB400>Lumináticos</color> é estritamente proibido aqui!",
  ui_story_5060_50600101_21_dialog_content = "Ei, estou falando de você! O <color=#FFB400>semi-humano</color> mexendo com fogo aí! Pare seu espetáculo de rua! Agora mesmo!",
  ui_story_5060_50600101_22_dialog_content = "Foi mal! Desculpe! Vou indo agora... Ai, isso dói!",
  ui_story_5060_50600101_23_dialog_content = "Como é que o Deus da Luz escolheu abençoar encrenqueiros como você com Luminática...",
  ui_story_5060_50600101_24_dialog_content = "Ei! O que você está olhando? Afaste-se! Não bloqueie o caminho!",
  ui_story_5060_50600101_25_dialog_content = "...",
  ui_story_5060_50600101_26_dialog_content = "O que está acontecendo? Os semi-humanos estão causando problemas de novo? Fiquem longe deles, pessoal...",
  ui_story_5060_50600101_27_dialog_content = "Hum... Existem também raças <color=#FFB400>semi-humanas</color> e <color=#FFB400>magias</color> semelhantes em minha terra natal...",
  ui_story_5060_50600101_28_dialog_content = "Mas aqui, eles os chamam de <color=#FFB400>aurorianos semi-humanos</color> e <color=#FFB400>Luminatics</color>, certo?",
  ui_story_5060_50600101_29_dialog_content = "Há algo estranho sobre a <color=#FFB400>mana</color> neste mundo, e isso está me impedindo de <color=#FFB400>me transformar de volta em um dragão</color>. Se não fosse pelos meus poderes estarem limitados...",
  ui_story_5060_50600101_30_dialog_content = "Eu ensinaria uma lição a esses cavaleiros altivos e poderosos agora mesmo!",
  ui_story_5060_50600101_31_dialog_content = "Aquele castelo branco flutuante lá em cima parece bem suspeito. Aposto que é a base de operações desses cavaleiros.",
  ui_story_5060_50600101_32_dialog_content = "Preso em um estranho novo mundo com poderes limitados e sob os olhares cautelosos de alguns de seus habitantes...",
  ui_story_5060_50600101_33_dialog_content = "Nessa situação, devo usar a força para intimidar as pessoas ao meu redor primeiro?",
  ui_story_5060_50600101_34_dialog_content = "Assim, posso ganhar mais tempo para reunir minhas forças e procurar Kanna e os outros.",
  ui_story_5060_50600101_35_dialog_content = "Urgh... Não, acho que preciso reabastecer minha energia primeiro. Eu me pergunto como é o dinheiro neste mundo?",
  ui_story_5060_50600101_36_dialog_content = "Pastéis de Longzhou recém-assados! Deliciosos e leves no paladar! Ei, jovem senhora, quer experimentar um pedaço?",
  ui_story_5060_50600101_37_dialog_content = "Uma mordida? Isso significa que é de graça?",
  ui_story_5060_50600101_38_dialog_content = "Com certeza! Experimente primeiro e compre se gostar do sabor. Nós até fazemos entregas, então você pode enviar para seus amigos distantes.",
  ui_story_5060_50600101_39_dialog_content = "(Eu realmente preciso confirmar se podemos comer com segurança a comida deste mundo...)",
  ui_story_5060_50600101_40_dialog_content = "Hum? Isso é realmente muito bom!",
  ui_story_5060_50600101_41_dialog_content = "Uau! Impressionante!",
  ui_story_5060_50600101_42_dialog_content = "Você manuseia esses pauzinhos com destreza. Já esteve em <color=#FFB400>Longzhou</color>?",
  ui_story_5060_50600101_43_dialog_content = "Huh? De jeito nenhum. Onde fica esse lugar chamado \"Longzhou\"?",
  ui_story_5060_50600101_44_dialog_content = "É o meu local de nascimento, um continente estrangeiro com uma cultura próspera e comida deliciosa. Meu lugar, o Restaurante do Liu, é especializado em culinária de Longzhou.",
  ui_story_5060_50600101_45_dialog_content = "(Longzhou... Será que este restaurante tem algo a ver com os dragões que estou procurando?)",
  ui_story_5060_50600101_46_dialog_content = "E esse lugar, o que é?",
  ui_story_5060_50600101_47_dialog_content = "Aqui está a Baixa Lumópolis, o coração de <color=#FFB400>Astra</color>. Temos comerciantes de todo o continente aqui—",
  ui_story_5060_50600101_48_dialog_content = "Espere, senhorita, você está perdida?",
  ui_story_5060_50600101_49_dialog_content = "De certa forma, sim. Para ser honesto, também não tenho certeza do que aconteceu.",
  ui_story_5060_50600101_50_dialog_content = "Você está sofrendo de perda de memória ou abdução?! Se estiver em apuros, estamos todos aqui para ajudar!",
  ui_story_5060_50600101_51_dialog_content = "Que tal entrar para tomar uma bebida quente e fazer uma pausa?",
  ui_story_5060_50600101_52_dialog_content = "(As pessoas daqui também podem ser muito legais...)",
  ui_story_5060_50600101_53_dialog_content = "Obrigado. Eu me separei dos meus amigos. Só preciso encontrá-los antes de voltar para casa.",
  ui_story_5060_50600101_54_dialog_content = "Há algo que eu gostaria de perguntar a você... Perdão, mas posso saber seu nome?",
  ui_story_5060_50600101_55_dialog_content = "Sou o proprietário e chef do Restaurante Liu. Pode me chamar apenas de Liu.",
  ui_story_5060_50600101_56_dialog_content = "Se precisar de ajuda, senhorita, é só me avisar!",
  ui_story_5060_50600101_57_dialog_content = "Deixe-me me apresentar. Meu nome é Tohru e eu estava pensando... May Posso trabalhar no seu restaurante por um tempo?",
  ui_story_5060_50600101_58_dialog_content = "Eu sei que acabamos de nos conhecer e ainda tenho muito a aprender sobre este lugar... Mas minhas habilidades como empregada são de primeira!",
  ui_story_5060_50600101_59_dialog_content = "Cozinhar, limpar e receber convidados são como uma segunda natureza para mim! Tenho certeza de que posso ser útil para o seu restaurante!",
  ui_story_5060_50600101_60_dialog_content = "Aqui está seu pedido de Tofu Nevado! Aproveite!",
  ui_story_5060_50600101_61_dialog_content = "Uau, impressionante! A comida aqui é servida bem rápido.",
  ui_story_5060_50600101_62_dialog_content = "Aqui está o mais novo especial do Chef Liu: Sopa Dourada de Frutos do Mar! Por favor, tenha cuidado, pois está muito quente!",
  ui_story_5060_50600101_63_dialog_content = "Ah, tá bom.",
  ui_story_5060_50600101_64_dialog_content = "Aqui está um novo par de pauzinhos. Se você tiver dificuldade em usá-los... Nós também temos facas e garfos! Aqui está!",
  ui_story_5060_50600101_65_dialog_content = "Tohru, temos alguns clientes!",
  ui_story_5060_50600101_66_dialog_content = "Entendi! Prontos, pessoal? Um, dois, três—",
  ui_story_5060_50600101_67_dialog_content = "Bem-vindo!",
  ui_story_5060_50600101_68_dialog_content = "Devo dizer, hoje foiwill be a shock to, foi um, um choque. Raramente vejo tant-1",
  ui_story_5060_50600101_69_dialog_content = "Sua performance foi realmente incrível, Srta. Tohru! Esse comprometimento com o serviço é o que chamamos de espírito de empregada...",
  ui_story_5060_50600101_70_dialog_content = "Isso mesmo! Esse é o espírito de verdadeira dedicação de uma donzela!",
  ui_story_5060_50600101_71_dialog_content = "Oh céus, nunca pensei que teria a chance de pegar algo tão novo e emocionante nesta idade.",
  ui_story_5060_50600101_72_dialog_content = "O mesmo vale para mim! Aprendi muito com a maneira como você analisa e prepara seus pratos!",
  ui_story_5060_50600101_73_dialog_content = "Aprender a fazer novos pratos sempre me faz imaginar qual será a expressão dela quando eu servi-los para ela...",
  ui_story_5060_50600101_74_dialog_content = "(Tudo bem, vou aprender várias receitas que o Kobayashi pode gostar e testá-las quando eu voltar!)",
  ui_story_5060_50600101_75_dialog_content = "Chefe, estamos de volta!",
  ui_story_5060_50600101_76_dialog_content = "Bom ver vocês retornarem em segurança. Então, vocês encontraram algum <color=#FFB400>Aurorianos com características de dragão</color> que a Srta. Tohru mencionou?",
  ui_story_5060_50600101_77_dialog_content = "Não, nenhuma pista nisso. Quanto ao novo negócio...",
  ui_story_5060_50600101_78_dialog_content = "Você quer dizer o serviço de entrega, certo? Sem pressa; vá com calma.",
  ui_story_5060_50600101_79_dialog_content = "O cara responsável pelo novo negócio desistiu novamente, alegando que oferecer serviços de entrega em Astra seria muito arriscado.",
  ui_story_5060_50600101_80_dialog_content = "Então, tivemos que encontrar outra pessoa para substituir.",
  ui_story_5060_50600101_81_dialog_content = "Entendi fractious\nEntendi I chaotically basing on the fact that the majority of the time, the majority of the time, the majority of the time, the majority of, the majority of the time Hogan. S. S., the is spo 25  can 25% of the  the majority of the time on the market, and the inverted 0.0 the0.5% of the time, part the Bank ,  in the 25,  25, our 25, our25, our25, our25, our25, our25 there is a 25 /our micr. To be completed by continually. 1,  a mach. The, the. d. 50,000,000, and. 50. 50,000, ,",
  ui_story_5060_50600101_82_dialog_content = "Talvez precisemos contratar profissionais como membros da União Mensageira para lidar com isso...",
  ui_story_5060_50600101_83_dialog_content = "Eu queria perguntar, mas os \"<color=#FFB400>Eclipsitas</color>\" são algum tipo de monstros?",
  ui_story_5060_50600101_84_dialog_content = "Sempre que as pessoas mencionam eles, seus rostos ficam pálidos.",
  ui_story_5060_50600101_85_dialog_content = "Tohru, você não sabe sobre Eclipsitas?!",
  ui_story_5060_50600101_86_dialog_content = "Bem, eu realmente venho de um lugar muito distante, sabe.",
  ui_story_5060_50600101_87_dialog_content = "Não consigo imaginar o quão longe precisamos estar para ficar longe dos Eclipsitas.",
  ui_story_5060_50600101_88_dialog_content = "Os Eclipsitas fazem parte deste mundo desde que nós, Aurorianos, estabelecemos nossa própria história.",
  ui_story_5060_50600101_89_dialog_content = "Eles têm aparências horríveis e força selvagem, frequentemente viajando em grupos, causando estragos no campo.",
  ui_story_5060_50600101_90_dialog_content = "Às vezes, sob o comando de líderes poderosos, eles até atacam cidades e espalham o caos.",
  ui_story_5060_50600101_91_dialog_content = "Parece que viver neste mundo não é tão fácil quanto parece.",
  ui_story_5060_50600101_92_dialog_content = "Haha, mas todos nós já nos acostumamos. Cabeça erguida, e ainda podemos nos virar.",
  ui_story_5060_50600101_93_dialog_content = "Agora, vamos discutir como podemos ajudar a Srta. Tohru a encontrar o caminho de casa!",
  ui_story_5060_50600101_94_dialog_content = "Obrigado a todos. Para ser sincero, eu sei o caminho de volta para casa, mas tive um pequeno problema...",
  ui_story_5060_50600101_95_dialog_content = "(Os níveis de <color=#FFB400>mana</color> neste mundo são muito instáveis para que o portal seja ativado corretamente...)",
  ui_story_5060_50600101_96_dialog_content = "(Agora, preciso encontrar um local onde os níveis de mana estejam relativamente equilibrados, para que eu possa testar o portal sem interferências...)",
  ui_story_5060_50600101_97_dialog_content = "(Mas eu não posso simplesmente deixar Kanna e os outros presos neste mundo...)",
  ui_story_5060_50600101_98_dialog_content = "(Preciso de dinheiro se quiser viajar e coletar informações também. Não posso ficar dependendo só da generosidade do Sr. Liu...)",
  ui_story_5060_50600101_99_dialog_content = "Ahh, que estresse! É assim que o Kobayashi deve se sentir como chefe da nossa casa!",
  ui_story_5060_50600101_100_dialog_content = "Chefe, más notícias! O novo pedido de entrega mais uma vez não foi concluído!",
  ui_story_5060_50600101_101_dialog_content = "Qual o motivo dessa vez?",
  ui_story_5060_50600101_102_dialog_content = "De acordo com nosso entregador, o cliente em Umbraton foi sequestrado pelos capangas da Guilda...",
  ui_story_5060_50600101_103_dialog_content = "Hã?!",
  ui_story_5060_50600101_104_dialog_content = "Da última vez, a ponte em frente à casa do cliente foi destruída pelos Eclipsitas...",
  ui_story_5060_50600101_105_dialog_content = "E da vez anterior, o cliente desapareceu no Território Secreto... Não tem como manter nosso negócio assim.",
  ui_story_5060_50600101_106_dialog_content = "(Serviço de entrega? Essa pode ser minha chance de explorar os arredores e ganhar dinheiro ao mesmo tempo!)",
  ui_story_5060_50600101_107_dialog_content = "Sr. Liu! Que tal eu assumir o trabalho de entrega e cuidar do resto desses pedidos não entregues?",
  ui_story_5060_50600101_108_dialog_content = "Contanto que eu leve as coisas a sério, monstros e bandidos não têm chance contra mim!",
  ui_story_5060_50600101_109_dialog_content = "(Esta seria a maneira perfeita para eu ganhar dinheiro e aprender sobre este mundo enquanto procuro por Kanna e os outros.)",
  ui_story_5060_50600101_110_dialog_content = "Entretanto the last with out,",
  ui_story_5060_50600101_111_dialog_content = "Não faria mais sentido buscar ajuda de mensageiros alados...",
  ui_story_5060_50600101_112_dialog_content = "Bem, se estamos falando de asas, eu também tenho!",
  ui_story_5060_50600101_113_dialog_content = "Ser capaz de voar é uma habilidade essencial para uma empregada profissional. Agora observe isso... Ai!",
  ui_story_5060_50600101_114_dialog_content = "D-Desculpe, parece que eu comi demais quando cheguei aqui.",
  ui_story_5060_50600101_115_dialog_content = "Então já vou indo!",
  ui_story_5060_50600101_116_dialog_content = "Senhorita Tohru, se você quer evitar atenção desnecessária, é melhor não abusar dessas habilidades especiais dos demi-humanos aqui...",
  ui_story_5060_50600101_117_dialog_content = "Tudo bem ir devagar, sabe. A segurança vem em primeiro lugar!",
  ui_story_5060_50600101_118_dialog_content = "Tohru! Boa sorte lá fora!",
  ui_story_5060_50600101_119_dialog_content = "Entendido! Vou garantir a conclusão de todos os pedidos e trazer muitas avaliações positivas! Apenas deixe comigo—",
  ui_story_5060_50600101_120_dialog_content = "Aqui vou eu, Astra!",
  ui_story_5060_50600101_121_dialog_content = "Esta entregadora Empregada Dragão está dando tudo de si!",
  ui_story_5060_50600201_1_dialog_content = "Prest forever21 automatically andor. Escut a color=\"# and to all of foul, foul, foul, foul, foul, foul, foul, foul, foul, foul, foul, all foul, foul, foul, foul, foul, foul, foul, foul, foul, foul,  in the last text, foul, foul, rays on the Fleurieu Peninsula south SSPictures of the Caelestlets. Hiking, swimming, fishing, kayaking, sailing, snorkeling, diving, whale watching, adventure playground, boat ramp, bbq facilities, kiosk, outdoor cinema, live screenshots, and a 3, and a 3, and.",
  ui_story_5060_50600201_2_dialog_content = "Exatamente! Eles realmente serão extintos!",
  ui_story_5060_50600201_3_dialog_content = "Bah, canalhas! Como ousam pegar alguém tão indefeso quanto PlayerName como refém?!",
  ui_story_5060_50600201_4_dialog_content = "Lute comigo um a um, seus covardes!",
  ui_story_5060_50600201_5_dialog_content = "Isso mesmo, Kobayashi diz que as pessoas devem lutar de forma justa em um duelo.",
  ui_story_5060_50600201_6_dialog_content = "Então me enfrentem um a um, seus covardes!",
  ui_story_5060_50600201_7_dialog_content = "Bem dito, <color=#FFB400>Kanna</color>! Pronto para uma luta?",
  ui_story_5060_50600201_8_dialog_content = "Sim. Graças ao Tessa, minha energia está totalmente recarregada.",
  ui_story_5060_50600201_9_dialog_content = "Ha—",
  ui_story_5060_50600201_10_dialog_content = "Espere aí, você não concordou com uma luta um-a-um? Você também vai eletrocutar o refém!?",
  ui_story_5060_50600201_11_dialog_content = "Na verdade, eu não me importo mesmo!",
  ui_story_5060_50600201_12_dialog_content = "Sobrevivi a quedas, chuvas torrenciais, ataques psíquicos, ferimentos relacionados a ferramentas e até mesmo a objetos estranhos inseridos no meu corpo...",
  ui_story_5060_50600201_13_dialog_content = "Depois de passar por tudo isso, você realmente acha que eu tenho medo de uma pequena eletrocução?!",
  ui_story_5060_50600201_14_dialog_content = "O quê? Os celestitas são sempre tão fora de linha?",
  ui_story_5060_50600201_15_dialog_content = "Heh. Do jeito que vocês estão agora, não conseguiriam nem arranhar um Celestita. Além disso...",
  ui_story_5060_50600201_16_dialog_content = "Nunca roubamos a <color=#FFB400>coleção</color> sobre a qual você está falando. Isso deve ser algum tipo de mal-entendido.",
  ui_story_5060_50600201_17_dialog_content = "Então desistam disso. Vocês também precisam comer, certo? Se continuarmos assim, minha comida para viagem vai esfriar.",
  ui_story_5060_50600201_18_dialog_content = "M-Mas... vocês foram os únicos presentes quando aquilo desapareceu! Quem mais deveríamos suspeitar?!",
  ui_story_5060_50600201_19_dialog_content = "Ou, sabe... você poderia simplesmente se oferecer para pagar por isso.",
  ui_story_5060_50600201_20_dialog_content = "Então eu sinto muito mesmo—",
  ui_story_5060_50600201_21_dialog_content = "<size=45>Não vou pagar um único Nightium. Nem pense nisso!</size>",
  ui_story_5060_50600201_22_dialog_content = "O que devemos fazer, chefe? Não consigo enfrentar nenhum desses caras sozinho e também não podemos simplesmente recuar assim...",
  ui_story_5060_50600201_23_dialog_content = "Seu idiota inútil! Claro que não podemos recuar agora. Essa coisa é muito importante para nossos senhores...",
  ui_story_5060_50600201_24_dialog_content = "Foi roubado por aquele auroriano demi-humano que aparenta ter menos de dez anos de idade!",
  ui_story_5060_50600201_25_dialog_content = "Então agora você está colocando isso em uma garotinha? Você realmente não tem vergonha.",
  ui_story_5060_50600201_26_dialog_content = "Parece que vou ter que te ensinar uma lição da maneira mais difícil, afinal.",
  ui_story_5060_50600201_27_dialog_content = "?",
  ui_story_5060_50600201_28_dialog_content = "Não dê ouvidos a essas pessoas ruins ou às mentiras delas, Kanna.",
  ui_story_5060_50600201_29_dialog_content = "Assim que tirarmos eles, vou dividir um dos meus pirulitos com você.",
  ui_story_5060_50600201_30_dialog_content = "Está se aproximando.",
  ui_story_5060_50600201_31_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_5060_50600201_32_dialog_content = "Essa sensação... Está se aproximando, sem dúvida alguma.",
  ui_story_5060_50600201_33_dialog_content = "<color=#e8d9bb>Zumbido—Buzz—</color>",
  ui_story_5060_50600201_34_dialog_content = "Está aqui!",
  ui_story_5060_50600201_35_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5060_50600201_36_dialog_content = "Foi por pouco! Não estou muito atrasado, estou?!",
  ui_story_5060_50600201_37_dialog_content = "Agora sei como a Kobayashi se sente quando se esforça ao máximo para cumprir os prazos dos projetos...",
  ui_story_5060_50600201_38_dialog_content = "Aham! Só um momento enquanto confirmo as informações de contato do destinatário...",
  ui_story_5060_50600201_39_dialog_content = "Olá, PlayerName! Aqui está o seu pedido de entrega, por favor, lembre-se de nos dar uma avaliação de cinco estrelas!",
  ui_story_5060_50600201_40_dialog_content = "Além disso, a loja está procurando por uma criança perdida com chifres de dragão na cabeça, que pode controlar a eletricidade. Se você tiver alguma informação relevante...",
  ui_story_5060_50600201_41_dialog_content = "Tohru—! É você, Tohru!",
  ui_story_5060_50600201_42_dialog_content = "K-Kanna?!",
  ui_story_5060_50600201_43_dialog_content = "Estive procurando por você em todos os lugares! Não esperava te encontrar aqui!",
  ui_story_5060_50600201_44_dialog_content = "*Aconchegar, aconchegar* Tohru!",
  ui_story_5060_50600201_45_dialog_content = "Eu não fazia ideia de que a amiga que você estava procurando era uma senhora tão bonita, Kanna...",
  ui_story_5060_50600201_46_dialog_content = "Parece que ajudamos a realizar o desejo dela afinal, né?",
  ui_story_5060_50600201_47_dialog_content = "Muito obrigado por cuidar do Kanna!",
  ui_story_5060_50600201_48_dialog_content = "Sem problemas!",
  ui_story_5060_50600201_49_dialog_content = "Mas falando em problemas, temos mesmo que colocar esses bandidos em seu lugar.",
  ui_story_5060_50600201_50_dialog_content = "Droga—o idiota realmente chamou reforços?",
  ui_story_5060_50600201_51_dialog_content = "Minha... cabeça... está girando...",
  ui_story_5060_50600201_52_dialog_content = "Tch, achei que fosse alguém importante! Mas é só uma empregada!",
  ui_story_5060_50600201_53_dialog_content = "E-Eclipsitas?! Quem é essa donzela, capaz de fazer os Eclipsitas virem em seu auxílio?",
  ui_story_5060_50600201_54_dialog_content = "Corram! Avanço tático para trás!",
  ui_story_5060_50600201_55_dialog_content = "Se eu tivesse que adivinhar, foi a Srta. Tohru que os atraiu para cá.",
  ui_story_5060_50600201_56_dialog_content = "Então esses são os Eclipsitas, né? Eles estiveram me perseguindo todo esse tempo, mas eu estava tão preocupado em me atrasar que mal os percebi.",
  ui_story_5060_50600201_57_dialog_content = "Mas agora que seu pedido foi entregue, posso lidar com eles imediatamente!",
  ui_story_5060_50600201_58_dialog_content = "Huh? Um monte de luzes de cores diferentes acabou de aparecer na minha frente!",
  ui_story_5060_50600201_59_dialog_content = "Esses devem ser os rastros de luz que o PlayerName estava falando.",
  ui_story_5060_50600201_60_dialog_content = "Se seguir certos rastros de luz, você pode eliminar o inimigo rapidamente!",
  ui_story_5060_50600201_61_dialog_content = "Entendi. Então essa é a lei deste mundo?",
  ui_story_5060_50600201_62_dialog_content = "É como um jogo, então não deve ser muito difícil!",
  ui_story_5060_50600201_63_dialog_content = "Tudo bem! Agora que sei as regras, é hora de brincar!",
  ui_story_5060_50600201_64_dialog_content = "Tohru sempre fica tão animada quando se trata de destruir seus inimigos.",
  ui_story_5060_50600202_1_dialog_content = "Isso foi incrível, Senhorita Tohru! Não imaginava que você usaria sua cauda para derrotar os Eclipsitas!",
  ui_story_5060_50600202_2_dialog_content = "Se Vice estivesse aqui, ela com certeza gostaria de fazer amizade com você!",
  ui_story_5060_50600202_3_dialog_content = "Manter a elegância e a postura mesmo durante a batalha é uma habilidade básica para qualquer verdadeira empregada doméstica!",
  ui_story_5060_50600202_4_dialog_content = "(Jogar Eclipsitas no ar com sua cauda... isso pode realmente ser considerado \"elegante\"? Parece que ela pode ensinar uma coisa ou duas ao Vice...)",
  ui_story_5060_50600202_5_dialog_content = "Permita-me expressar minha gratidão mais uma vez. Kanna é um membro muito precioso da minha família.",
  ui_story_5060_50600202_6_dialog_content = "Estive tão preocupado desde que nos separamos. Obrigado a vocês dois pela ajuda!",
  ui_story_5060_50600202_7_dialog_content = "Não sei se realmente merecemos tudo isso...",
  ui_story_5060_50600202_8_dialog_content = "Para dizer a verdade, nós não fizemos muito pelo Kanna. Você é quem apareceu e salvou o dia, Srta. Tohru.",
  ui_story_5060_50600202_9_dialog_content = "Posso ver que vocês dois são boas pessoas, não são? Por favor, não se preocupem, eu só queria agradecer!",
  ui_story_5060_50600202_10_dialog_content = "PlayerName e Tessa são boas pessoas.",
  ui_story_5060_50600202_11_dialog_content = "Eles cuidaram de mim, me deram doces e até me ajudaram a te encontrar.",
  ui_story_5060_50600202_12_dialog_content = "Mas aqueles outros caras eram pessoas más.",
  ui_story_5060_50600202_13_dialog_content = "Na verdade, Tessa e eu estávamos em um leilão clandestino quando esbarramos em Kanna.",
  ui_story_5060_50600202_14_dialog_content = "Não era exatamente um lugar para crianças pequenas, então fomos perguntar sobre a situação dela.",
  ui_story_5060_50600202_15_dialog_content = "Mas, justo quando estávamos nos preparando para escoltá-la para longe, um bando de bandidos pulou em nós.",
  ui_story_5060_50600202_16_dialog_content = "Esses idiotas nos acusaram de roubar os tesouros que eles estavam prestes a exibir, a chamada \"<color=#FFB400>coleção</color>.\"",
  ui_story_5060_50600202_17_dialog_content = "E foi assim que todos nós acabamos aqui.",
  ui_story_5060_50600202_18_dialog_content = "Kanna, você realmente não comeu o tesouro deles?",
  ui_story_5060_50600202_19_dialog_content = "Não mesmo.",
  ui_story_5060_50600202_20_dialog_content = "Mas o interior da caixa do tesouro tinha um cheiro tão familiar... Eu não pude evitar de tocá-lo...",
  ui_story_5060_50600202_21_dialog_content = "Não se sinta culpada, Kanna! Aqueles caras eram um bando de idiotas maldosos, mas você é uma boa garota!",
  ui_story_5060_50600202_22_dialog_content = "*Aconchegar, aconchegar* Tessa...",
  ui_story_5060_50600202_23_dialog_content = "Sua eletricidade... É agradável...",
  ui_story_5060_50600202_24_dialog_content = "Ah... Ela está se aconchegando em meus braços novamente.",
  ui_story_5060_50600202_25_dialog_content = "O-O que devo fazer?",
  ui_story_5060_50600202_26_dialog_content = "Desculpe, ela não costuma ser assim! Afinal, este é um mundo novo e estranho para ela, então é normal que ela se sinta um pouco confusa.",
  ui_story_5060_50600202_27_dialog_content = "Agora, Kanna, isso não é educado. Se você precisa de mana, pode comer um pouco da minha.",
  ui_story_5060_50600202_28_dialog_content = "Sua mana tem um gosto ruim.",
  ui_story_5060_50600202_29_dialog_content = "O quê? Minha mana tem um gosto perfeitamente bom!",
  ui_story_5060_50600202_30_dialog_content = "Tohru... Quando podemos ir para casa?",
  ui_story_5060_50600202_31_dialog_content = "Eu também quero ir para casa, mas primeiro precisamos encontrar um lugar onde o mana seja estável o suficiente para ativar o portal.",
  ui_story_5060_50600202_32_dialog_content = "Estou triste. Sinto falta do Saikawa.",
  ui_story_5060_50600202_33_dialog_content = "Não se preocupe, tenho certeza que encontraremos um jeito de voltar àquele mundo em breve.",
  ui_story_5060_50600202_34_dialog_content = "Falando nisso, queria te perguntar sobre isso...",
  ui_story_5060_50600202_35_dialog_content = "Você mencionou isso mais cedo, durante nossa luta contra os Eclipsitas agora há pouco - Que vocês dois são de outro mundo.",
  ui_story_5060_50600202_36_dialog_content = "Você não estava brincando... Estava?",
  ui_story_5060_50600202_37_dialog_content = "Embora seja verdade que suas aparências são bem semelhantes ao que conhecemos como aurorianos semi-humanos...",
  ui_story_5060_50600202_38_dialog_content = "Nunca vi ninguém ou algo absorver e liberar energia da mesma forma que você faz.",
  ui_story_5060_50600202_39_dialog_content = [[
exemplar-0-., and the- dignified, and , , in, and I'm not sure:,.2007island and this is
3: 5 to the best of my ability royalty]],
  ui_story_5060_50600202_40_dialog_content = "Isso é igual àqueles mangás.",
  ui_story_5060_50600202_41_dialog_content = "Infelizmente, ainda não nos reconectamos com a maior parte do nosso grupo...",
  ui_story_5060_50600202_42_dialog_content = "O personagem principal do mangá está em grandes apuros agora.",
  ui_story_5060_50600202_43_dialog_content = "Você tem lido mangás demais, Kanna.",
  ui_story_5060_50600202_44_dialog_content = "A luta acabou. Estou cansado.",
  ui_story_5060_50600202_45_dialog_content = "Está com pressa, senhorita Tohru?",
  ui_story_5060_50600202_46_dialog_content = "Eu estou... Mas ainda tenho bastante tempo para entregar meu próximo pedido.",
  ui_story_5060_50600202_47_dialog_content = "Então, você poderia me contar sobre o seu mundo enquanto faz uma pausa aqui?",
  ui_story_5060_50600202_48_dialog_content = "Parece que você está morrendo de vontade de saber sobre a história de amor entre Kobayashi e eu! Ficarei feliz em contar tudo para você!",
  ui_story_5060_50600202_49_dialog_content = "É uma longa história, então é melhor você estar preparado para isso!",
  ui_story_5060_50600202_50_dialog_content = "Claro. Posso comer meu almoço enquanto você faz isso, embora tenho certeza que já esfriou...",
  ui_story_5060_50600202_51_dialog_content = "Isso não é nada! Só precisa de um pouco de calor!",
  ui_story_5060_50600202_52_dialog_content = "V-Você consegue cuspir fogo?! Isso é raro, até mesmo no nosso mundo!",
  ui_story_5060_50600202_53_dialog_content = "Uau! A comida está quente de novo!",
  ui_story_5060_50600202_54_dialog_content = "A temperatura está perfeita... Você deve ter um controle perfeito sobre suas chamas, Senhorita Tohru!",
  ui_story_5060_50600202_55_dialog_content = "Por favor, aproveitem suas refeições enquanto eu entretenho todos vocês com minha história!",
  ui_story_5060_50600202_56_dialog_content = "<color=#e8d9bb>Tohru compartilha apaixonadamente a história de seu encontro e vínculo com uma jovem chamada Kobayashi.</color>",
  ui_story_5060_50600202_57_dialog_content = "<color=#e8d9bb>No entanto, de acordo com Kanna, parece que Tohru incorporou muitas de suas próprias imaginações subjetivas na história...</color>",
  ui_story_5060_50600202_58_dialog_content = "Ah, eu vejo.",
  ui_story_5060_50600202_59_dialog_content = "Um mundo sem Eclipsitas ou noites intermináveis, onde todos vivem em paz e ordem... Eu realmente quero ver isso por mim mesmo.",
  ui_story_5060_50600202_60_dialog_content = "Parece que você também é muito próximo da Srta. Kobayashi.",
  ui_story_5060_50600202_61_dialog_content = "Tenho certeza que ela ficará muito preocupada se você não encontrar um jeito de voltar ao mundo dela em breve.",
  ui_story_5060_50600202_62_dialog_content = "É isso mesmo, por isso decidi trabalhar como donzela entregadora!",
  ui_story_5060_50600202_63_dialog_content = "Assim, posso ganhar dinheiro enquanto procuro meus amigos desaparecidos. Quando todos estivermos juntos novamente, podemos concentrar nossos esforços em encontrar um caminho para casa!",
  ui_story_5060_50600202_64_dialog_content = "Espere... Talvez se Kobayashi me ver depois de desaparecer por três dias, ela possa... Heeheehee...",
  ui_story_5060_50600202_65_dialog_content = "Sem pensamentos impuros, Tohru.",
  ui_story_5060_50600202_66_dialog_content = "Ainda assim, sinto falta do Kobayashi também.",
  ui_story_5060_50600202_67_dialog_content = "Então, além de encontrar seus amigos, você também precisa encontrar um lugar especial para que seu portal funcione, certo?",
  ui_story_5060_50600202_68_dialog_content = "Se for assim, sugiro que vá com PlayerName para ver a Guilda Cloudrover.",
  ui_story_5060_50600202_69_dialog_content = "Uma das corretoras de informações mais profissionais de todo o Astra está lá. Ela pode ser capaz de te ajudar.",
  ui_story_5060_50600202_70_dialog_content = "Hã? Você não vem junto, Tessa?",
  ui_story_5060_50600202_71_dialog_content = "Não esqueça, viemos aqui para fazer um trabalho de escolta para o leilão.",
  ui_story_5060_50600202_72_dialog_content = "Agora que terminamos, um de nós precisa relatar ou teremos feito isso em vão.",
  ui_story_5060_50600202_73_dialog_content = "Uau, como eu pude quase esquecer... Conto com você então, Tessa!",
  ui_story_5060_50600202_74_dialog_content = "Sigam-me, vocês dois! Acontece que eu tenho uma boa relação com o líder da Guilda Cloudrover.",
  ui_story_5060_50600202_75_dialog_content = "A Guilda Cloudrover... Esse nome me parece familiar, mas onde foi que eu ouvi isso antes...?",
  ui_story_5060_50600202_76_dialog_content = "Eh?! Não é lá que preciso entregar meu próximo pedido?!",
  ui_story_5060_50600202_77_dialog_content = "E o motivo pelo qual não foi entregue na última vez...",
  ui_story_5060_50600202_78_dialog_content = "Foi porque o destinatário estava ocupado demais lutando contra um bando de gângsteres!",
  ui_story_5060_50600301_1_dialog_content = "É a mesma Guilda Cloudrover?!",
  ui_story_5060_50600301_2_dialog_content = "Deixe-me dar uma olhada no nome deles mais uma vez... \"<color=#FFB400>Um Assistente Muito Importante</color>\"?",
  ui_story_5060_50600301_3_dialog_content = "Senhora Sheol, Senhora Sheol! Você está aqui?",
  ui_story_5060_50600301_4_dialog_content = "A guilda está tão quieta agora... Espere, o que é isso?!",
  ui_story_5060_50600301_5_dialog_content = "O arquivo foi arrombado. Os documentos de inteligência e contas estão espalhados pelo chão. Será que foram roubados?",
  ui_story_5060_50600301_6_dialog_content = "Se for assim, isso significa que nosso cliente provavelmente está com problemas!",
  ui_story_5060_50600301_7_dialog_content = "Eu esperava algo assim, então pode deixar comigo! Acontece que sou especialista em punir malfeitores!",
  ui_story_5060_50600301_8_dialog_content = "Mas você costumava ser o pior dos piores.",
  ui_story_5060_50600301_9_dialog_content = "Sinceramente, Kanna, não diga coisas assim! Não é legal!",
  ui_story_5060_50600301_10_dialog_content = "Ei, pessoal, vocês estão aqui para ver nosso chefe, presumo?",
  ui_story_5060_50600301_11_dialog_content = "Receio que nosso chefe esteja ocupado com o trabalho ultimamente e não possa receber visitantes pessoalmente. Se você tiver alguma dúvida, por favor, fale com nosso novo assistente.",
  ui_story_5060_50600301_12_dialog_content = "A Senhora Sheol não está aqui? E ela também contratou um novo assistente?",
  ui_story_5060_50600301_13_dialog_content = "Será que essa pessoa é o \"Assistente Muito Importante\" que encomendou essa comida?",
  ui_story_5060_50600301_14_dialog_content = "Se ela estiver, você poderia por favor avisá-la que a entregadora do restaurante chegou com o pedido dela?",
  ui_story_5060_50600301_15_dialog_content = "Além disso, PlayerName e eu também gostaríamos de fazer algumas perguntas a esta guilda, se for aceitável...",
  ui_story_5060_50600301_16_dialog_content = "Eu pedi-Com UV lasting 6-.hemp  1, which is as a. This takeout can will be at least  Aug applications and its materials; born to existing  2015-2016-2017",
  ui_story_5060_50600301_17_dialog_content = "Infelizmente, nossa guilda está lidando com um pequeno problema no momento. Receio que não temos tempo para saborear as delícias do seu restaurante agora.",
  ui_story_5060_50600301_18_dialog_content = "Vou receber o delivery em nome do nosso chefe e acertar a conta.",
  ui_story_5060_50600301_19_dialog_content = "Você vê, a guilda está atualmente lidando com...",
  ui_story_5060_50600301_20_dialog_content = "Você deve ser o famoso PlayerName, nosso parceiro Celestita, certo?",
  ui_story_5060_50600301_21_dialog_content = "O famoso...",
  ui_story_5060_50600301_22_dialog_content = "Celestita...?",
  ui_story_5060_50600301_23_dialog_content = "P-Por favor, não me chame assim! Você está me envergonhando na frente dos meus novos amigos!",
  ui_story_5060_50600301_24_dialog_content = "Eu entendo. Desculpe se isso está causando algum inconveniente.",
  ui_story_5060_50600301_25_dialog_content = "Acontece que temos alguns assuntos internos para discutir com você, PlayerName. Se importaria de nos acompanhar lá fora?",
  ui_story_5060_50600301_26_dialog_content = "Vocês duas, adoráveis senhoras, por favor, aguardem um pouco na sala de recepção.",
  ui_story_5060_50600301_27_dialog_content = "Ah—Temos que esperar?",
  ui_story_5060_50600301_28_dialog_content = "Será que vocês dois gostariam de aproveitar nossos itens especiais enquanto esperam?",
  ui_story_5060_50600301_29_dialog_content = "Nossa Guilda Cloudrover coletou vários tesouros exóticos das Cidades Subterrâneas de Illumina, Deserto Rediesel, Corte do Norte e muito mais...",
  ui_story_5060_50600301_30_dialog_content = "Nossa, tantos fofos e bonitos—",
  ui_story_5060_50600301_31_dialog_content = "Se você encontrar algum tesouro que chame sua atenção, ficaremos mais do que felizes em oferecê-lo com desconto, como um sinal de nossa amizade.",
  ui_story_5060_50600301_32_dialog_content = "Mas eu não tenho dinheiro.",
  ui_story_5060_50600301_33_dialog_content = "Ahem! Sabe, Kanna, eu já fui pago pelo meu trabalho. Não custa gastar um pouco disso...",
  ui_story_5060_50600301_34_dialog_content = "Sério? Você é o melhor, Tohru!",
  ui_story_5060_50600301_35_dialog_content = "Então, o que exatamente aconteceu com a guilda? Parece bem sério.",
  ui_story_5060_50600301_36_dialog_content = "Você ficou sabendo do agitado leilão clandestino em Umbraton e Baixa Lumópolis recentemente?",
  ui_story_5060_50600301_37_dialog_content = "Como uma das guildas mais renomadas de Astra, nossa Guilda Cloudrover também é uma grande patrocinadora do leilão.",
  ui_story_5060_50600301_38_dialog_content = "Mas ultimamente, as coisas têm saído do controle no leilão, com pessoas insistindo que seus itens expostos foram roubados.",
  ui_story_5060_50600301_39_dialog_content = "Eles estão fazendo acusações infundadas e provocando brigas com outros participantes, causando um caos total.",
  ui_story_5060_50600301_40_dialog_content = "Senhora Sheol está trabalhando duro para resolver este assunto.",
  ui_story_5060_50600301_41_dialog_content = "Ah... É isso...",
  ui_story_5060_50600301_42_dialog_content = "Esses encrenqueiros até invadiram nossa Guilda, causando o tumulto que você acabou de presenciar.",
  ui_story_5060_50600301_43_dialog_content = "Nós nos esforçamos tanto para transportar as peças do leilão e agora elas desapareceram. Não deveria você, a Guilda Cloudrover, ser responsabilizada?",
  ui_story_5060_50600301_44_dialog_content = "A coleção foi roubada sob sua vigilância, então você tem que pagar por isso!",
  ui_story_5060_50600301_45_dialog_content = "Caso contrário, o senhor de Lumópolis que nos contratou não vai te perdoar!",
  ui_story_5060_50600301_46_dialog_content = "Isso mesmo. Eu sugiro que todos vocês membros da Guilda Cloudrover cooperem com nossa investigação e não vão contra o nosso senhor.",
  ui_story_5060_50600301_47_dialog_content = "Então até os soldados particulares trabalhando para os nobres de Lumópolis estão envolvidos nisso, né? Que nojo.",
  ui_story_5060_50600301_48_dialog_content = "Coleções raras geralmente são reservadas por nobres influentes; é uma rotina comum.",
  ui_story_5060_50600301_49_dialog_content = "Para eles, dar lances é apenas uma demonstração de seu poder e status.",
  ui_story_5060_50600301_50_dialog_content = "No entanto, o que pode irritá-los levemente se tornaria um verdadeiro fardo para nós, comerciantes.",
  ui_story_5060_50600301_51_dialog_content = "Se não fosse pela previsão do chefe em trazer um assistente capaz para lidar com eles, estaríamos sobrecarregados.",
  ui_story_5060_50600301_52_dialog_content = "Então, como a Senhora Sheol planeja lidar com isso?",
  ui_story_5060_50600301_53_dialog_content = "Ela suspeita que esses itens desapareceram das caixas bem antes de chegarem ao local do leilão.",
  ui_story_5060_50600301_54_dialog_content = "É por isso que ela espera que você, que tem uma ligação próxima com ela, possa dar uma mãozinha neste assunto.",
  ui_story_5060_50600301_55_dialog_content = "Tente usar suas habilidades psíquicas como Celestita para ver se consegue encontrar alguma pista sobre os itens desaparecidos e confirmar suas suspeitas.",
  ui_story_5060_50600301_56_dialog_content = "...Então, desculpe decepcionar todos vocês...",
  ui_story_5060_50600301_57_dialog_content = "Na verdade, eu fui um dos convidados que foi abordado no leilão mais cedo...",
  ui_story_5060_50600301_58_dialog_content = "Pra esclarecer, tentei usar minhas habilidades psíquicas para procurar pistas, mas não encontrei nada.",
  ui_story_5060_50600301_59_dialog_content = "Receio que o caixote contendo a coleção realmente esteja vazio!",
  ui_story_5060_50600301_60_dialog_content = "Que pena. Parece que teremos que contar com o assistente para manter essas pessoas ocupadas.",
  ui_story_5060_50600301_61_dialog_content = "Se você puder nos ajudar a resolver isso, nossa chefe certamente expressará sua gratidão.",
  ui_story_5060_50600301_62_dialog_content = "A gratidão de Sheol, hein...",
  ui_story_5060_50600301_63_dialog_content = "Você foi uma grande ajuda para mim, meu amigo...",
  ui_story_5060_50600301_64_dialog_content = "Parece que preciso elevar você um ou dois degraus nas minhas estimativas.",
  ui_story_5060_50600301_65_dialog_content = "Agora me diga, como devo compensá-lo adequadamente pelos seus problemas...?",
  ui_story_5060_50600301_66_dialog_content = "...E-Eu não me importo em ajudar, mas vou dispensar a gratidão da Senhora Sheol! Eu realmente não aguento mais isso!!",
  ui_story_5060_50600301_67_dialog_content = "Hum, acho que vou passar.",
  ui_story_5060_50600301_68_dialog_content = "Huh? De quem é essa voz?",
  ui_story_5060_50600301_69_dialog_content = "Assistente <color=#FFB400>Lucoa</color>!",
  ui_story_5060_50600301_70_dialog_content = "(Espera, essa senhora super madura é a assistente sobre a qual estávamos falando antes?!)",
  ui_story_5060_50600301_71_dialog_content = "(Ela realmente tem uma vibe parecida com a Senhora Sheol... Mas ela parece ser muito mais amigável.)",
  ui_story_5060_50600301_72_dialog_content = "Ah, você também está aqui? Sinto muito mesmo, mas ainda tenho um trabalho a fazer, sabe!",
  ui_story_5060_50600301_73_dialog_content = "Esses bandidos são realmente dedicados aos seus trabalhos. Eu tenho tentado o meu melhor para persuadi-los, mas eles ainda não cedem...",
  ui_story_5060_50600301_74_dialog_content = "Ei, pessoal, fiquem atentos. Essa garota não é uma Aurorian comum... Tem algo muito estranho nela!!",
  ui_story_5060_50600301_75_dialog_content = "Sei que pareço um pouco diferente, mas isso não é motivo para ser tão cauteloso!",
  ui_story_5060_50600301_76_dialog_content = "Estou mais do que feliz em conversar e encontrar uma solução para esse problema!",
  ui_story_5060_50600301_77_dialog_content = "Não se deixe enganar pela aparência dela! Hmph, ela acha que pode nos conquistar com palavras doces e nós simplesmente iremos embora? Não é tão fácil assim!",
  ui_story_5060_50600301_78_dialog_content = "No final do dia, ela é apenas uma garota demi-humana, nem mesmo digna de ser serva dos senhores de Uptown.",
  ui_story_5060_50600301_79_dialog_content = "Vamos todos nos unir contra ela, pessoal. Com certeza a derrubaremos e então a usaremos como moeda de troca!",
  ui_story_5060_50600301_80_dialog_content = "Oh? Que assustador!",
  ui_story_5060_50600301_81_dialog_content = "Deixe-a em paz, seus idiotas podres—",
  ui_story_5060_50600301_82_dialog_content = "Nossa, um verdadeiro cavaleiro veio ao meu resgate! Estou muito grato!",
  ui_story_5060_50600301_83_dialog_content = "Mas como o <color=#FFB400>Assistente Muito Importante</color> da guilda, eu também posso ser bastante útil em uma luta.",
  ui_story_5060_50600302_1_dialog_content = "Eles simplesmente não param de chegar... Você está bem, Senhorita Lucoa?",
  ui_story_5060_50600302_2_dialog_content = "Estou perfeitamente bem! Se for o caso, deve ser difícil para você me apoiar enquanto se protege, PlayerName.",
  ui_story_5060_50600302_3_dialog_content = "E-espere, onde você aprendeu meu nome?",
  ui_story_5060_50600302_4_dialog_content = "Da Senhora Sheol, é claro! Ela me falou tanto sobre você...",
  ui_story_5060_50600302_5_dialog_content = "Maldições! O trabalho dos senhores não está terminado. Levantem-se — não ousem nos subestimar!",
  ui_story_5060_50600302_6_dialog_content = "Eu gostaria que todos vocês soubessem ler o ambiente e agir adequadamente.",
  ui_story_5060_50600302_7_dialog_content = "Vocês estão todos fora de controle... O que significa que terei que levar as coisas um pouco mais a sério... Crianças boazinhas, lembrem-se de desviar o olhar!",
  ui_story_5060_50600302_8_dialog_content = "E-Ei! Por que você está cobrindo meus olhos?",
  ui_story_5060_50600302_9_dialog_content = "O que?... O-o-o que é essa criatura?! Ugh...",
  ui_story_5060_50600302_10_dialog_content = "Ufa... Você pode olhar agora. Esses caras devem estar um pouco mais quietos agora.",
  ui_story_5060_50600302_11_dialog_content = "(Hã? Uau... O que diabos o Lucoa fez com aqueles bandidos..?)",
  ui_story_5060_50600302_12_dialog_content = "(Parece que eles acabaram de ser jogados em um poço cheio de Eclipsitas de alto nível...)",
  ui_story_5060_50600302_13_dialog_content = "Deixe-me sentir ao redor...",
  ui_story_5060_50600302_14_dialog_content = "Isso é... Uma pena...?",
  ui_story_5060_50600302_15_dialog_content = "Ah—Eu disse sem espiar!",
  ui_story_5060_50600302_16_dialog_content = "D-Desculpe! Eu só estava curioso sobre seu poder, só isso...",
  ui_story_5060_50600302_17_dialog_content = "Ah? Então você está curioso para ver minha verdadeira forma?",
  ui_story_5060_50600302_18_dialog_content = "Sabe, você é tão fofo quanto o <color=#FFB400>Shouta</color> quando eu olho mais de perto!",
  ui_story_5060_50600302_19_dialog_content = "O rosto que você faz ao usar seus poderes é especialmente fofo. Então este é o Celestita sobre o qual ouvi falar tanto!",
  ui_story_5060_50600302_20_dialog_content = "Que rostinho fofo... Você se importa se eu tocá-lo?",
  ui_story_5060_50600302_21_option_content = "Fora, demônio!",
  ui_story_5060_50600302_22_dialog_content = "Ai, isso realmente dói. Eu não sou um demônio de jeito nenhum...",
  ui_story_5060_50600302_23_dialog_content = "Agora sou uma boa pessoa!",
  ui_story_5060_50600302_24_dialog_content = "Qualquer outra pessoa já teria denunciado você aos Guardiões de Lumópolis há muito tempo!!",
  ui_story_5060_50600302_25_option_content = "M-Mas eu vou ficar sufocado...",
  ui_story_5060_50600302_26_dialog_content = "N-não tem outros assuntos da guilda para cuidar, Srta. Lucoa...?",
  ui_story_5060_50600302_27_dialog_content = "Este lugar é perigoso, afinal. Quem sabe quando aqueles soldados particulares aparecerão para investigar... Hahaha...",
  ui_story_5060_50600302_28_dialog_content = "Para (or \"para ser sinc, as well as the other translations, I'm less of an assistant and more of on the other Leni the to be's\">Para ser sinc, para ser sincero, sou menos um assistente e mais um guarda-cost (or \"guarda-costas\") que a Senhora Sheol contratou para este assunto.",
  ui_story_5060_50600302_29_dialog_content = "Na verdade, sou bastante poderoso e posso lidar com a maioria das situações.",
  ui_story_5060_50600302_30_dialog_content = "Afinal, por acaso sou uma deusa em minha terra natal...",
  ui_story_5060_50600302_31_dialog_content = "Lu—co—a—",
  ui_story_5060_50600302_32_dialog_content = "Hmm? É você, Tohru?",
  ui_story_5060_50600302_33_dialog_content = "Tenho me esforçado ao máximo para encontrar uma maneira de reativar o portal...",
  ui_story_5060_50600302_34_dialog_content = "Mesmo assim você está aqui relaxando?!",
  ui_story_5060_50600302_35_dialog_content = "E se chamando de \"Assistente Muito Importante\"...",
  ui_story_5060_50600302_36_dialog_content = "Nossa! Como você descobriu meu disfarce neste mundo, Tohru...?",
  ui_story_5060_50600302_37_dialog_content = "Lucoa foi exposto.",
  ui_story_5060_50600302_38_dialog_content = "Ah! Não me diga que você é quem está entregando minha comida, Tohru?",
  ui_story_5060_50600302_39_dialog_content = "Uma entregadora vestida de empregada... Que ideia interessante!",
  ui_story_5060_50600302_40_dialog_content = "Desde que percebi o quão diferente é a mana neste mundo, tenho tentado encontrar uma maneira de melhorar a capacidade do meu corpo de convertê-la.",
  ui_story_5060_50600302_41_dialog_content = "Desse jeito, posso usar meus poderes para identificar a localização exata de todos.",
  ui_story_5060_50600302_42_dialog_content = "Infelizmente, como a maioria das pessoas aqui tende a usar esses chamados \"Luminatics\" para resolver seus problemas...",
  ui_story_5060_50600302_43_dialog_content = "Não consegui encontrar uma criança tão talentosa quanto Shouta para formar um pacto temporário comigo.",
  ui_story_5060_50600302_44_dialog_content = "Graças a Deus ninguém se machucou até agora.",
  ui_story_5060_50600302_45_dialog_content = "Mas não posso dizer que não estou interessado neste Celestita de quem todos falam! Se for o caso, tenho grandes expectativas para ele!",
  ui_story_5060_50600302_46_dialog_content = "Dá um tempo, Lucoa!",
  ui_story_5060_50600302_47_dialog_content = "Ahem! De qualquer forma, conseguimos encontrar Lucoa, o que significa que agora só precisamos encontrar Elma e Fafnir.",
  ui_story_5060_50600302_48_dialog_content = "Bem, Lucoa? Todos dizem que essa guilda é uma das melhores fontes de informação.",
  ui_story_5060_50600302_49_dialog_content = "Você descobriu alguma coisa sobre esses dois?",
  ui_story_5060_50600302_50_dialog_content = "Tenho prestado muita atenção em tudo relacionado a dragões ou semi-humanos com características de dragão.",
  ui_story_5060_50600302_51_dialog_content = "Minha pista mais recente envolve o desaparecimento de uma coleção de um leilão, que é no que estou trabalhando agora.",
  ui_story_5060_50600302_52_dialog_content = "Hã? Então você também está investigando esses bandidos? E é porque eles têm algo a ver com dragões?",
  ui_story_5060_50600302_53_dialog_content = "Claro. Minha intuição nunca mente, sabe?",
  ui_story_5060_50600302_54_dialog_content = "Lucoa está ficando sério.",
  ui_story_5060_50600302_55_dialog_content = "A maioria desses bandidos trabalha para uma gangue de contrabando, e um deles menciona acidentalmente que o item desaparecido é um tesouro escondido de um dragão.",
  ui_story_5060_50600302_56_dialog_content = "Um tesouro que só foi obtido após arriscar a morte sob as garras de um dragão.",
  ui_story_5060_50600302_57_dialog_content = "Um de nós deixou cair algo? Talvez Fafnir...?",
  ui_story_5060_50600302_58_dialog_content = "Provavelmente não...",
  ui_story_5060_50600302_59_dialog_content = "Caso contrário, eles seriam amaldiçoados.",
  ui_story_5060_50600302_60_dialog_content = "Você tem razão.",
  ui_story_5060_50600302_61_dialog_content = "Senhorita Lucoa, gostaria de fazer algumas perguntas, se estiver tudo bem?",
  ui_story_5060_50600302_62_dialog_content = "Senhora Sheol queria usar meus poderes para localizar a coleção perdida.",
  ui_story_5060_50600302_63_dialog_content = "Mas quando tentei usá-los no leilão, não sei se foi falta de informação ou algo mais...",
  ui_story_5060_50600302_64_dialog_content = "Minhas habilidades psíquicas não funcionaram.",
  ui_story_5060_50600302_65_dialog_content = "Poderia me contar mais sobre essa coleção desaparecida? Ou talvez mais informações sobre essa gangue de contrabandistas?",
  ui_story_5060_50600302_66_dialog_content = "Sei o que você está pensando. Como um Celestita, você precisa estar familiarizado com algo para poder senti-lo com seus poderes, certo?",
  ui_story_5060_50600302_67_dialog_content = "Os contrabandistas em questão geralmente trabalham para as classes altas de Umbraton e Lumopolis. Eles se especializam em caçar grandes criaturas e vasculhar ruínas em busca de artefatos.",
  ui_story_5060_50600302_68_dialog_content = "Os itens que trouxeram para exposição desta vez foram principalmente espécimes e peles de criaturas raras e valiosas.",
  ui_story_5060_50600302_69_dialog_content = "Eles podem até ter trazido um espécime vivo...",
  ui_story_5060_50600302_70_dialog_content = "Isso explicaria por que o topo daquela caixa estava tão quente...",
  ui_story_5060_50600302_71_dialog_content = "Espere, você também encontrou uma pista, Kanna?!",
  ui_story_5060_50600302_72_dialog_content = "Bem, Kanna? Como o tesouro desapareceu?",
  ui_story_5060_50600302_73_dialog_content = "Provavelmente... Provavelmente porque ele cresceu pernas e fugiu!",
  ui_story_5060_50600302_74_dialog_content = "Err...",
  ui_story_5060_50600302_75_dialog_content = "Além de mangás, eu me pergunto se estou deixando você ler muitos contos de fadas também...",
  ui_story_5060_50600302_76_dialog_content = ".... a major, like the one you see in the app, I'm still not convinced that the app is the best way...: Still not convinced,, like; will be a great of the best examples of the;, and I can't help but feel like myoy some features one of these, but I can't help but feel like my kagura is missing something: Because., but I can. The best to me, like, the best examples of the best examples of the originality of the best examples Archive of the best examples of the best examples, and the best, are the best examples of the best examples of the best examples of the best examples of the best examples of the best examples: 2021-02-11T19:00:00Z: I cannot help but feel like my kagura is missing something: is the best for adapted to the best examples in Elsewhere honeymoon be in   with the best examples of the best examples of the best examples of the best examples, I cannot help but feel a few of the best examples, especially the best examples of the ODIs. I have a, and I have a lot of them. I have a lot of them. I have a lot of them. I have a trampoline 2018 and",
  ui_story_5060_50600302_77_dialog_content = "Ainda não consigo sentir onde isso está.",
  ui_story_5060_50600302_78_dialog_content = "Não fique frustrado, PlayerName. Você já fez tanto.",
  ui_story_5060_50600302_79_dialog_content = "Eu sei, mas não é todo dia que posso ajudar a todos e ainda ganhar favores da Senhora Sheol. Eu gostaria de poder fazer mais...",
  ui_story_5060_50600302_80_dialog_content = "Aqui vem minha chance.",
  ui_story_5060_50600302_81_dialog_content = "Venha aqui, pequena celestita! Dê um abraço!",
  ui_story_5060_50600302_82_dialog_content = "Waaaah! S-S-Solte...!",
  ui_story_5060_50600302_83_dialog_content = "Que reação morna, PlayerName.",
  ui_story_5060_50600302_84_dialog_content = "Graças à sua influência, tenho uma compreensão muito mais abrangente deste mundo. De certa forma, é como se compartilhássemos a mesma mente, apesar de termos corpos separados.",
  ui_story_5060_50600302_85_dialog_content = "Deixe-me passar meu poder para você!",
  ui_story_5060_50600302_86_dialog_content = "A-Aquilo foi só eu usando minhas habilidades psíquicas antes! Eu estava apenas ajudando você a ver os rastros de luz!",
  ui_story_5060_50600302_87_dialog_content = "Pare com isso, ou vou denunciar você à Senhora Sheol!",
  ui_story_5060_50600302_88_dialog_content = "É mesmo? Eu e a Senhora Sheol somos bem próximos, sabia? Ela até me deu algo que eu realmente queria como adiantamento do meu salário!",
  ui_story_5060_50600302_89_dialog_content = "Infelizmente, como recebi uma homenagem, não posso mais fazer o que quiser.",
  ui_story_5060_50600302_90_dialog_content = "Se apresse Tohru, ou PlayerName pode morrer...",
  ui_story_5060_50600302_91_dialog_content = "Ugh, sinceramente... Você ainda parece estar fazendo o que quer, Lucoa.",
  ui_story_5060_50600302_92_dialog_content = "Se você tem tanto tempo livre assim, por que não me ajuda a entregar esses pedidos?!",
  ui_story_5060_50600302_93_dialog_content = "De qualquer forma, PlayerName, você tem certeza de que quer nos ajudar?",
  ui_story_5060_50600302_94_dialog_content = "Você não tem outros trabalhos ou investigações para fazer?",
  ui_story_5060_50600302_95_dialog_content = "Podemos ir juntos?",
  ui_story_5060_50600302_96_dialog_content = "Não dig a,-se assim, <lock_ of lock- se, Kanna. PlayerName é is a, alguém muito importante neste im, neste mundo..",
  ui_story_5060_50600302_97_dialog_content = "Tenho certeza de que ele tem muitas coisas igualmente importantes para fazer agora.",
  ui_story_5060_50600302_98_dialog_content = "Na verdade, eu não sei... E eu realmente não sou tão importante assim, Senhorita Tohru. De qualquer forma, para onde vai seu próximo pedido?",
  ui_story_5060_50600302_99_dialog_content = "Deixe-me ver, acho que era um posto avançado em um lugar chamado \"Posto Avançado Illumina.\"",
  ui_story_5060_50600302_100_dialog_content = "Então isso não deve ser um problema! Eu preciso ir lá também!",
  ui_story_5060_50600302_101_dialog_content = "Como um posto avançado nas fronteiras, deve haver muitos contrabandistas atuando na área. Aposto que encontraremos muitas informações lá!",
  ui_story_5060_50600302_102_dialog_content = "Eba, vamos embarcar em outra aventura!",
  ui_story_5060_50600302_103_dialog_content = "Para economizar tempo, por que não voamos até lá?",
  ui_story_5060_50600302_104_dialog_content = "Huh? Como você sabia que eu poderia me transformar em um dragão, PlayerName? Não me lembro de ter te contado isso.",
  ui_story_5060_50600302_105_dialog_content = "Hã?",
  ui_story_5060_50600302_106_dialog_content = "Eu quis dizer que podemos ir com o Soroz até o Posto Avançado de Illumina. Sobre o que você estava falando, Srta. Tohru?",
  ui_story_5060_50600302_107_dialog_content = "S... Sor-o quê?",
  ui_story_5060_50600401_1_dialog_content = "Então isso é Soroz, PlayerName? Seu amigo é tão pequeno...",
  ui_story_5060_50600401_2_dialog_content = "Ei! Soroz ficaria muito chateado se você o confundisse com uma aeronave comum!",
  ui_story_5060_50600401_3_dialog_content = "Você vai entender quando chegar lá... Eu aposto que Soroz não é menor do que nenhum dragão que você mencionou até agora.",
  ui_story_5060_50600401_4_dialog_content = "Sério? Estou ainda mais animado para ver!",
  ui_story_5060_50600401_5_dialog_content = "Ainda assim, esta aeronave é muito pequena para transportar todos nós até Soroz em uma única viagem.",
  ui_story_5060_50600401_6_dialog_content = "Você disse algo sobre poder voar, certo, senhorita Tohru?",
  ui_story_5060_50600401_7_dialog_content = "Claro! Afinal, sou um dragão!",
  ui_story_5060_50600401_8_dialog_content = "Então você realmente pode voar?",
  ui_story_5060_50600401_9_dialog_content = "Quero andar de dirigível. Parece divertido.",
  ui_story_5060_50600401_10_dialog_content = "Nesse caso, eu vou ficar com Kanna.",
  ui_story_5060_50600401_11_dialog_content = "Você não pode tentar perder um pouco de peso, Lucoa? Não há espaço para minha moto...",
  ui_story_5060_50600401_12_dialog_content = "Ei PlayerName, posso te fazer uma pergunta?",
  ui_story_5060_50600401_13_dialog_content = "Claro, o que é?",
  ui_story_5060_50600401_14_dialog_content = "O que exatamente são aurorianos semi-humanos?",
  ui_story_5060_50600401_15_dialog_content = "Enquanto eu fazia entregas, avistei algumas crianças aladas voando pelo céu.",
  ui_story_5060_50600401_16_dialog_content = "Eles pareciam tão confortáveis e livres, e se pareciam muito conosco agora mesmo.",
  ui_story_5060_50600401_17_dialog_content = "Mas as pessoas de Lumópolis pareciam considerar seus chifres e asas como coisas ruins... Eu realmente não entendo o porquê, no entanto.",
  ui_story_5060_50600401_18_dialog_content = "Os nobres também implicaram com você enquanto estava em Lumópolis, Srta. Tohru?",
  ui_story_5060_50600401_19_dialog_content = "De forma alguma. Talvez tenha sido por causa da minha aura destrutiva; nenhum deles ousou se aproximar de mim.",
  ui_story_5060_50600401_20_dialog_content = "No entanto, eles dificultaram muito a vida dos outros demi-humanos que trabalhavam no restaurante do Sr. Liu. Eu não suportava vê-los.",
  ui_story_5060_50600401_21_dialog_content = "Há muitos motivos envolvidos, mas a raça e o status deles são definitivamente os maiores.",
  ui_story_5060_50600401_22_dialog_content = "Os verdadeiros semi-humanos eram incapazes de usar Luminatics, então foram dizimados há muito tempo.",
  ui_story_5060_50600401_23_dialog_content = "Os aurorianos semi-humanos que vemos hoje são descendentes dos verdadeiros semi-humanos que se casaram com aurorianos.",
  ui_story_5060_50600401_24_dialog_content = "Para os nobres de Lumo, essas pessoas indesejadas não são nada além de uma mancha em sua fé e em suas linhagens nobres.",
  ui_story_5060_50600401_25_dialog_content = "Ah, não isso de novo. Fé, linhagens puras, bênçãos... É por causa de ideias como essas que vemos os humanos como uma espécie tola e inferior.",
  ui_story_5060_50600401_26_dialog_content = "Felizmente, os aurorianos têm se tornado cada vez mais receptivos em relação aos aurorianos semi-humanos atualmente. Essa tendência também está acontecendo entre alguns nobres de Lumopolis...",
  ui_story_5060_50600401_27_dialog_content = "Ah, parece que estamos quase lá. Devemos conseguir ver Soroz assim que passarmos por essas nuvens.",
  ui_story_5060_50600401_28_dialog_content = "Pessoal, eu gostaria que vocês conhecessem meu amigo Soroz!",
  ui_story_5060_50600401_29_dialog_content = "Os Aurorianos deste mundo se referem ao seu tipo como os Colossos. Eles são os companheiros próximos dos Celestitas e só podem ser pilotados por nosso povo.",
  ui_story_5060_50600401_30_dialog_content = "Uau, é enorme! Espere, é Soroz... Um dragão totalmente mecânico?!",
  ui_story_5060_50600401_31_dialog_content = "Um dragão robô, igual nos filmes.",
  ui_story_5060_50600401_32_dialog_content = "Algo tão único assim deve ser realmente bom em combate, certo? Posso desafiá-lo para uma luta agora mesmo?!",
  ui_story_5060_50600401_33_dialog_content = "Ah... Soroz nunca esteve em batalha...",
  ui_story_5060_50600401_34_dialog_content = "Que pena.",
  ui_story_5060_50600401_35_dialog_content = "Enfim, vamos entrar.",
  ui_story_5060_50600401_36_dialog_content = "Uau—Que lindo!",
  ui_story_5060_50600401_37_dialog_content = "Este lugar também—",
  ui_story_5060_50600401_38_dialog_content = "Não incomode outras pessoas, Kanna!",
  ui_story_5060_50600401_39_dialog_content = "Não só há muito espaço, mas também é totalmente equipado e decorado com bom gosto. Morar aqui deve ser realmente conveniente!",
  ui_story_5060_50600401_40_dialog_content = "Aviso: aproximando-se do limite de peso. Por favor, evite carregar bagagem excessiva.",
  ui_story_5060_50600401_41_dialog_content = "...Eu não te disse, Lucoa? Você realmente deveria tentar perder algum peso.",
  ui_story_5060_50600401_42_dialog_content = "Sério? Quer dizer que não é a sua cauda gordinha nos pesando?",
  ui_story_5060_50600401_43_dialog_content = "Não se preocupe, provavelmente é apenas uma falha no sistema. Soroz é muito mais resistente do que isso.",
  ui_story_5060_50600401_44_dialog_content = "Parece que você realmente confia neste grande Colossus seu. Você deve ter uma relação maravilhosa com ele.",
  ui_story_5060_50600401_45_dialog_content = "Sim! Afinal, Soroz é um dos meus amigos mais próximos e importantes.",
  ui_story_5060_50600401_46_dialog_content = "Há mais de dez anos... Eu perdi minha casa, assim como toda a minha família.",
  ui_story_5060_50600401_47_dialog_content = "Eu não tive escolha a não ser aceitar que eu era o último Celestita vivo no mundo.",
  ui_story_5060_50600401_48_dialog_content = "Se não fosse o Soroz me fazendo companhia e me ensinando todos os tipos de coisas, eu não estaria onde estou hoje.",
  ui_story_5060_50600401_49_dialog_content = "Eu entendo.",
  ui_story_5060_50600401_50_dialog_content = "Minha relação com Kobayashi é exatamente a mesma. Como esperado, o amor não conhece limites, nem mesmo entre espécies!",
  ui_story_5060_50600401_51_dialog_content = "Eu-Eu não tenho certeza se é EXATAMENTE o mesmo.",
  ui_story_5060_50600401_52_dialog_content = "Então, você vê, Srta. Tohru, eu sei como é chegar a um mundo novo e estranho, e o medo e a desconfiança que acompanham isso.",
  ui_story_5060_50600401_53_dialog_content = "Mas graças à ajuda de Soroz e ao apoio de inúmeros amigos...",
  ui_story_5060_50600401_54_dialog_content = "Eu não me sinto mais tão sozinho e impotente no mundo.",
  ui_story_5060_50600401_55_dialog_content = "Então, quando vi o quanto você queria desesperadamente se reunir com seus amigos, meu coração me disse para ajudá-lo de todas as maneiras possíveis.",
  ui_story_5060_50600401_56_dialog_content = "Amigos são o nosso maior tesouro. Não sei por quanto tempo mais nossos mundos estarão conectados...",
  ui_story_5060_50600401_57_dialog_content = "Mas mesmo que seja apenas por um curto período, eu realmente espero que possamos ser amigos, Srta. Tohru!",
  ui_story_5060_50600401_58_dialog_content = "Quero ouvir ainda mais histórias sobre os outros mundos que você visitou... Assim como a história de amor entre você e a Srta. Kobayashi!",
  ui_story_5060_50600401_59_dialog_content = "Sinceramente, você tem muita coragem de dizer tudo isso...",
  ui_story_5060_50600401_60_dialog_content = "Não é óbvio que já somos amigos?",
  ui_story_5060_50600401_61_dialog_content = "Quando eu ativei o Portal de Teletransporte Mundial, eu originalmente pretendia voltar ao meu mundo natal e tirar algumas fotos dele...",
  ui_story_5060_50600401_62_dialog_content = "Mas sabe de uma coisa? Acho que a paisagem deste mundo também é muito bonita!",
  ui_story_5060_50600401_63_dialog_content = "Quando tudo isso acabar, vamos usar essa câmera para tirar uma foto de grupo, tá bom?",
  ui_story_5060_50600401_64_dialog_content = "...Sim! Eu gostaria disso!",
  ui_story_5060_50600401_65_dialog_content = "Você parece feliz, PlayerName.",
  ui_story_5060_50600401_66_dialog_content = "Lembre-se de sorrir assim para a foto.",
  ui_story_5060_50600401_67_dialog_content = "Hahaha! Eu definitivamente vou!",
  ui_story_5060_50600401_68_dialog_content = "<color=#e8d9bb>Mais tarde...</color>",
  ui_story_5060_50600401_69_dialog_content = "Estamos chegando perto do endereço de entrega.",
  ui_story_5060_50600401_70_dialog_content = "Qual é exatamente o propósito de construir um Posto Avançado de Illumina, PlayerName? Seria algum tipo de estrutura defensiva?",
  ui_story_5060_50600401_71_dialog_content = "Acho que você poderia dizer isso.",
  ui_story_5060_50600401_72_dialog_content = "Suspiro, a Federação Illumina realmente precisa reformular suas políticas de alimentação se seus soldados precisam pedir comida para se alimentarem.",
  ui_story_5060_50600401_73_dialog_content = "Por curiosidade, Tohru, o que o cliente pediu para comer?",
  ui_story_5060_50600401_74_dialog_content = "Sobremesas, com um acompanhamento de ainda mais sobremesa. Bem estranho para um cliente, né?",
  ui_story_5060_50600401_75_dialog_content = "Provavelmente é porque eles estão seriamente com falta de açúcar por aqui. Eu entendo completamente.",
  ui_story_5060_50600401_76_dialog_content = "Afinal, a guerra contra os Eclipsitas é extremamente perigosa. Sem energia suficiente, todos estariam em sérios apuros.",
  ui_story_5060_50600401_77_dialog_content = "Eclipsitas, hein? Sinceramente, não acho que eles sejam tão difíceis assim... Será que eles realmente representam uma ameaça tão grande para o mundo inteiro?",
  ui_story_5060_50600401_78_dialog_content = "Comparado aos Eclipsitas de agora pouco, você e seus amigos são incrivelmente poderosos.",
  ui_story_5060_50600401_79_dialog_content = "Mas na natureza, esses monstros não atacam em grupos, mas em ondas enormes.",
  ui_story_5060_50600401_80_dialog_content = "Nossa batalha contra os Eclipsitas é uma que nunca terminou.",
  ui_story_5060_50600401_81_dialog_content = "De certa forma, a história de Astra é uma história de nossas lutas contra os Eclipsitas.",
  ui_story_5060_50600401_82_dialog_content = "Você realmente não pode se dar ao luxo de baixar a guarda neste mundo, né?",
  ui_story_5060_50600401_83_dialog_content = "Olha, fumaça!",
  ui_story_5060_50600401_84_dialog_content = "Tohru, PlayerName, olhem lá embaixo! Os Eclipsitas estão atacando uma vila!",
  ui_story_5060_50600401_85_dialog_content = "Eu vejo! Só me dê um minuto e eu vou encontrar um lugar para pousar!",
  ui_story_5060_50600401_86_dialog_content = "Se muitos Eclipsitas atacarem, o posto avançado da Illumina pode não conseguir contê-los.",
  ui_story_5060_50600401_87_dialog_content = "Muitas pessoas estão feridas.",
  ui_story_5060_50600401_88_dialog_content = "Eu quero ajudá-los...",
  ui_story_5060_50600401_89_dialog_content = "Essas pessoas vivem vidas tão difíceis. Todos eles parecem tão cansados e com medo.",
  ui_story_5060_50600401_90_dialog_content = "É, e você pode perceber que alguns deles vieram de áreas ainda mais distantes e menos defendidas da Federação Illumina.",
  ui_story_5060_50600401_91_dialog_content = "Hã...",
  ui_story_5060_50600401_92_dialog_content = "Huh? Não!",
  ui_story_5060_50600401_93_dialog_content = "...",
  ui_story_5060_50600401_94_dialog_content = "E-eu queria ajudá-la, mas ela fugiu.",
  ui_story_5060_50600401_95_dialog_content = "Acredito que, após enfrentarem tanta destruição até agora, essas pessoas não têm forças para lidar com estranhos.",
  ui_story_5060_50600401_96_dialog_content = "Devemos deixar comida para eles aqui e dar bastante espaço para se acalmarem.",
  ui_story_5060_50600401_97_dialog_content = "Isso realmente não parece ser o momento para entregar pedidos de delivery...",
  ui_story_5060_50600401_98_dialog_content = "Ei! Prestem atenção, seus Eclipsitas podres!",
  ui_story_5060_50600401_99_dialog_content = "Se eu for denunciado por estar atrasado, você pode dar adeus ao seu mundo natal! Se você entende o que eu estou dizendo, então—",
  ui_story_5060_50600401_100_dialog_content = "... Esses caras são realmente incapazes de se comunicar?",
  ui_story_5060_50600401_101_dialog_content = "Acho que não tenho escolha... Mas quebrar um pouco as regras deste mundo.",
  ui_story_5060_50600501_1_dialog_content = "Tantos eclipses...",
  ui_story_5060_50600501_2_dialog_content = "Que saco! Eles realmente atacam em ondas!",
  ui_story_5060_50600501_3_dialog_content = "Se não houvesse pessoas da Federação Illumina espalhadas entre eles, eu poderia fritá-los todos com meu Sopro de Dragão...",
  ui_story_5060_50600501_4_dialog_content = "Façam o seu melhor, pessoal! Vou me esforçar para fornecer apoio moral também!",
  ui_story_5060_50600501_5_dialog_content = "Venha aqui e nos ajude!",
  ui_story_5060_50600501_6_dialog_content = "Eles devem ter construído um ninho em algum lugar por perto. Não chegaremos a lugar algum, a menos que o encontremos rapidamente e o destruamos.",
  ui_story_5060_50600501_7_dialog_content = "Deixe isso comigo! Assim que eu me transformar na minha forma de dragão...",
  ui_story_5060_50600501_8_dialog_content = "<size=45>Todos!</size>",
  ui_story_5060_50600501_9_dialog_content = "Os soldados Illumina e eu acabamos de destruir o ninho à nossa frente!",
  ui_story_5060_50600501_10_dialog_content = "Mantenha a linha e acabe com o restante das forças inimigas!",
  ui_story_5060_50600501_11_dialog_content = "Que todos os resquícios malignos sejam esmagados pelo poder da ordem!",
  ui_story_5060_50600501_12_dialog_content = "É o subcapitão <color=#FFB400>Elma</color>!",
  ui_story_5060_50600501_13_dialog_content = "A capitã Elma parece tão afiada!",
  ui_story_5060_50600501_14_dialog_content = "(Droga, estou morrendo de fome! Por que minha comida ainda não foi entregue?!)",
  ui_story_5060_50600501_15_dialog_content = "(Se essa comida tiver gosto ruim, com certeza vou deixar uma avaliação de uma estrela!)",
  ui_story_5060_50600502_1_dialog_content = "Ufa... Já se foram todos. Hora de recarregar.",
  ui_story_5060_50600502_2_dialog_content = "Hã...",
  ui_story_5060_50600502_3_dialog_content = "Ei, é a garota que fugiu de mim agora há pouco.",
  ui_story_5060_50600502_4_dialog_content = "Desculpe pelo que aconteceu antes... Eu estava com muito medo...",
  ui_story_5060_50600502_5_dialog_content = "Por isso eu fugi... Definitivamente, definitivamente não é porque eu não gosto de você.",
  ui_story_5060_50600502_6_dialog_content = "A batalha agora... foi realmente incrível!",
  ui_story_5060_50600502_7_dialog_content = "Você parece ter minha idade, mas... você é realmente arrojado, afiado e legal!",
  ui_story_5060_50600502_8_dialog_content = "Gostaria de te oferecer esta flor!",
  ui_story_5060_50600502_9_dialog_content = "Ah, ela fugiu de novo.",
  ui_story_5060_50600502_10_dialog_content = "Sim, mas parece que dessa vez ela fugiu por timidez em vez de medo.",
  ui_story_5060_50600502_11_dialog_content = "Acho que você acabou de fazer um novo amigo neste mundo, Kanna!",
  ui_story_5060_50600502_12_dialog_content = "Uma amiga...?",
  ui_story_5060_50600502_13_dialog_content = "Ela sempre estará me observando?",
  ui_story_5060_50600502_14_dialog_content = "Hahaha, tenho certeza que ela vai! Olha, mesmo se escondendo atrás daquela pedra ali, ela ainda está olhando para você!",
  ui_story_5060_50600502_15_dialog_content = "Terminei de recarregar agora.",
  ui_story_5060_50600502_16_dialog_content = "Bom! Agora que os Eclipsitas foram cuidados, é hora de entregar esta ordem ao seu legítimo dono.",
  ui_story_5060_50600502_17_dialog_content = "Sabe, encontrar ela como entregadora neste mundo realmente é um capricho do destino.",
  ui_story_5060_50600502_18_dialog_content = "Pela forma como você disse isso... Você conhece a pessoa que fez o pedido, Tohru? Eu pensei que fosse alguém da Federação Illumina?",
  ui_story_5060_50600502_19_dialog_content = "Não, ela é definitivamente uma das nossas. Ninguém mais faria um pedido assim.",
  ui_story_5060_50600502_20_dialog_content = "Não é mesmo, Elma?",
  ui_story_5060_50600502_21_dialog_content = "Minhas sobremesas! Elas finalmente apareceram!!!",
  ui_story_5060_50600502_22_dialog_content = "Huh? Tohru?! O que você está fazendo aqui?!",
  ui_story_5060_50600502_23_dialog_content = "Você ia comer todos esses antes de falar comigo...?",
  ui_story_5060_50600502_24_dialog_content = "Vim entregar sua comida!",
  ui_story_5060_50600502_25_dialog_content = "Tive que arrumar um emprego neste mundo só para ganhar dinheiro e procurar pistas sobre seu paradeiro, sabe...",
  ui_story_5060_50600502_26_dialog_content = "...E pelo tamanho deste pedido, você provavelmente pediu um de cada item do cardápio de sobremesas do Sr. Liu, não foi?!",
  ui_story_5060_50600502_27_dialog_content = "Não pude evitar! Quase morri de fome quando chegamos neste mundo!",
  ui_story_5060_50600502_28_dialog_content = "Não foi fácil, mas consegui usar minha clarividência para encontrar um passarinho com um panfleto amarrado na perna...",
  ui_story_5060_50600502_29_dialog_content = "E tudo no cardápio parecia tão delicioso!",
  ui_story_5060_50600502_30_dialog_content = "Então eu verifiquei todas as opções do cardápio de sobremesas e fiz um molho para mergulhar com líquidos de Eclipsitas!",
  ui_story_5060_50600502_31_dialog_content = "Depois disso, amarrei o cardápio de volta na perna do passarinho e o deixei voar!",
  ui_story_5060_50600502_32_dialog_content = "Mas então comecei a ficar com muita fome novamente à medida que mais Eclipsitas nos atacavam. Eu estava preocupado por não ter conseguido fazer meu pedido corretamente, já que minha comida nunca havia chegado.",
  ui_story_5060_50600502_33_dialog_content = "Mas no final, apareceu bem na hora! Heeheehee!",
  ui_story_5060_50600502_34_dialog_content = "Entendo. Nesse caso—",
  ui_story_5060_50600502_35_dialog_content = "Agradeço pelos seus serviços! Se gostou da comida, por favor, lembre-se de nos dar uma avaliação de cinco estrelas!",
  ui_story_5060_50600502_36_dialog_content = "Aqui está a conta da comida mais a entrega!",
  ui_story_5060_50600502_37_dialog_content = "Hã? O que você disse?",
  ui_story_5060_50600502_38_dialog_content = "<size=45>Aqui está a conta da comida mais a entrega!</size>",
  ui_story_5060_50600502_39_dialog_content = "...D-Desculpe, mas por acaso você aceita iene japonês...?",
  ui_story_5060_50600502_40_dialog_content = "Não seja bobo, caro cliente! Nossa loja só aceita Noitium, como você certamente sabe!",
  ui_story_5060_50600502_41_dialog_content = "Então entregue—todo o—seu Nightium—",
  ui_story_5060_50600502_42_dialog_content = "...Você está sendo muito assustador, Tohru!",
  ui_story_5060_50600502_43_dialog_content = "Eu vou cobrir a conta do Vice-Capitão. Afinal, ela salvou nossas vidas.",
  ui_story_5060_50600502_44_dialog_content = "Me inclua! A força do Vice-Capitão vale mais do que alguns Nightiums!",
  ui_story_5060_50600502_45_dialog_content = "*Soluce* Eu... estou tão emocionado, pessoal!",
  ui_story_5060_50600502_46_dialog_content = "Vamos descansar e nos reagrupar por enquanto, para podermos atacar o acampamento principal dos Eclipsitas! Exterminaremos todos eles!",
  ui_story_5060_50600502_47_dialog_content = "Esplendor Ilumina!!",
  ui_story_5060_50600502_48_dialog_content = "...",
  ui_story_5060_50600502_49_dialog_content = "PlayerName está muito atordoado para falar.",
  ui_story_5060_50600502_50_dialog_content = "Você continua tão ridículo quanto sempre, Elma.",
  ui_story_5060_50600502_51_dialog_content = "Como um dragão cumpridor das leis da Facção Harmonia, estou surpreso que você também esteja cumprindo suas responsabilidades neste mundo.",
  ui_story_5060_50600502_52_dialog_content = "E-eu tenho um bom motivo para isso... E você não pode falar nada, Tohru!",
  ui_story_5060_50600502_53_dialog_content = "Olhe só para você... Uma empregada dragão entregando comida oriental em uma moto...",
  ui_story_5060_50600502_54_dialog_content = "Você não está agindo como um dragão da Facção do Caos de jeito nenhum!",
  ui_story_5060_50600502_55_dialog_content = "Como eu disse, estou fazendo isso apenas para encontrar todos vocês e podermos voltar para casa mais cedo!",
  ui_story_5060_50600502_56_dialog_content = "Tohru e Elma são como fogo e água, como sempre.",
  ui_story_5060_50600502_57_dialog_content = "Heheheh, você ainda não entende os sentimentos entre velhos inimigos, Kanna.",
  ui_story_5060_50600502_58_dialog_content = "Vocês dois podem parecer que estão discutindo, mas na verdade não se odeiam, não é? Na verdade, vocês provavelmente se entendem muito bem!",
  ui_story_5060_50600502_59_dialog_content = "Agora que a batalha acabou e todos da Federação Illumina estão voltando...",
  ui_story_5060_50600502_60_dialog_content = "Por que não nos sentamos e comemos primeiro? Depois podemos conversar sobre procurar mais informações por aqui.",
  ui_story_5060_50600502_61_dialog_content = "Todos estão com fome, e o único que comeu foi Elma...",
  ui_story_5060_50600502_62_dialog_content = "...Mas tenho certeza de que ela consegue comer outra refeição.",
  ui_story_5060_50600502_63_dialog_content = "Tudo bem, estou dentro! Vamos comemorar nossa vitória com uma bela e grande festa!",
  ui_story_5060_50600502_64_dialog_content = "Isso cheira tão bem!",
  ui_story_5060_50600502_65_dialog_content = "Essa comida é incrível! Posso sentir meu poder voltando para mim!",
  ui_story_5060_50600502_66_dialog_content = "Hahaha, fico feliz que goste! Um amigo me ensinou a fazer isso há um tempo.",
  ui_story_5060_50600502_67_dialog_content = "Como esperado, nós, aurorianos e celestitas, somos os parceiros perfeitos!",
  ui_story_5060_50600502_68_dialog_content = "Mas você é um dragão.",
  ui_story_5060_50600502_69_dialog_content = "Todo mundo aqui fica dizendo isso, mas eu não me preocupo com pequenos detalhes assim!",
  ui_story_5060_50600502_70_dialog_content = "Suspiro, o que vamos fazer com você...",
  ui_story_5060_50600502_71_dialog_content = "Eu trouxe alguns pãezinhos no vapor do Sr. Liu também. Experimentem, pessoal!",
  ui_story_5060_50600502_72_dialog_content = "Guarde um pouco para mim, Tohru!",
  ui_story_5060_50600502_73_dialog_content = "Kanna disse algo sobre vocês dois serem como água e fogo, não foi?",
  ui_story_5060_50600502_74_dialog_content = "As pessoas geralmente não descrevem amigos dessa maneira. Qual é a história entre vocês dois?",
  ui_story_5060_50600502_75_dialog_content = "Acho que você pode dizer que somos amigos agora, mas costumávamos ser inimigos mortais.",
  ui_story_5060_50600502_76_dialog_content = "Sou um dragão da Facção Caos, enquanto ela pertence à Facção Harmonia.",
  ui_story_5060_50600502_77_dialog_content = "É meio difícil imaginar que vocês dois eram inimigos apenas por causa de suas facções.",
  ui_story_5060_50600502_78_dialog_content = "Conflito é inevitável em qualquer mundo, afinal.",
  ui_story_5060_50600502_79_dialog_content = "No mundo de onde viemos...",
  ui_story_5060_50600502_80_dialog_content = "Nós talvez não tenhamos que lidar com criaturas repugnantes como Eclipsitas todos os dias, como no seu mundo...",
  ui_story_5060_50600502_81_dialog_content = "Sempre haverá criaturas com pontos de vista diferentes. Naturalmente, o mesmo vale para os dragões que se recusam a se dar bem.",
  ui_story_5060_50600502_82_dialog_content = "Mas ainda quero acreditar no que Kobayashi me disse...",
  ui_story_5060_50600502_83_dialog_content = "Se todos estiverem dispostos a se comunicar e tratar uns aos outros como aliados, então não haverá mais conflitos no mundo.",
  ui_story_5060_50600502_84_dialog_content = "Assim como quando misturamos sua comida com os pães no vapor do Sr. Liu, tudo fica duas vezes mais delicioso!",
  ui_story_5060_50600502_85_dialog_content = "Acho que Elma vai comer tudo sozinha.",
  ui_story_5060_50600502_86_dialog_content = "Hahaha, concordo. As metáforas do Vice-Capitão são realmente peculiares.",
  ui_story_5060_50600502_87_dialog_content = "Lembro-me de quando conheci a Vice-Capitã; ela costumava ser um pouco reservada, falando sobre etiqueta e regras o tempo todo.",
  ui_story_5060_50600502_88_dialog_content = "Agora, ela se tornou uma excelente soldado de posto avançado! Ser um pouco estranha não é grande coisa.",
  ui_story_5060_50600502_89_dialog_content = "É estranho, mas desde que nos reencontramos, Elma não me contou nada sobre perturbar a ordem do mundo...",
  ui_story_5060_50600502_90_dialog_content = "Ou voltar para onde eu pertenço.",
  ui_story_5060_50600502_91_dialog_content = "Ela também não nivelou montanhas ou destruiu casas das pessoas em nome da manutenção da ordem.",
  ui_story_5060_50600502_92_dialog_content = "Pare de tentar causar confusão, Tohru...",
  ui_story_5060_50600502_93_dialog_content = "Tudo bem, Capitão-adjunto, eu tenho alguns doces aqui.",
  ui_story_5060_50600502_94_dialog_content = "Sei que você gosta de doces, então isso é tudo para você.",
  ui_story_5060_50600502_95_dialog_content = "Ah, vocês são os melhores! Estou tão feliz por ter encontrado um trabalho assim no seu mundo...",
  ui_story_5060_50600502_96_dialog_content = "Vocês sempre serão meus amigos!",
  ui_story_5060_50600502_97_dialog_content = "Você está fazendo amigos de forma um pouco casual demais, não acha?",
  ui_story_5060_50600502_98_dialog_content = "Sinceramente, como você consegue se integrar em qualquer ambiente em que se encontra?",
  ui_story_5060_50600502_99_dialog_content = "Todos na Facção Harmonia têm esse presente?",
  ui_story_5060_50600601_1_dialog_content = "Encontramos os criminosos que PlayerName mencionou! Eles vieram aqui do Deserto Rediesel.",
  ui_story_5060_50600601_2_dialog_content = "Naquela época, descobrimos que essas pessoas estavam tentando passar sorrateiramente pelo nosso posto usando métodos proibidos.",
  ui_story_5060_50600601_3_dialog_content = "Enquanto estávamos negociando e tentando prendê-los, fomos emboscados por Eclipsitas e não conseguimos capturá-los.",
  ui_story_5060_50600601_4_dialog_content = "Graças à intervenção do Subcapitão Elma, fomos salvos; caso contrário, teríamos sido enterrados nas areias amarelas com certeza.",
  ui_story_5060_50600601_5_dialog_content = "Não mencione! Vocês também me salvaram de morrer de fome no meio do nada, lembram?",
  ui_story_5060_50600601_6_dialog_content = "Bem, parece que encontraremos uma fortaleza ou rota de transporte para os contrabandistas em algum lugar do Deserto Rediesel.",
  ui_story_5060_50600601_7_dialog_content = "Vir a este Posto Avançado da Illumina foi a decisão certa, afinal!",
  ui_story_5060_50600601_8_dialog_content = "Mas ainda não ouvimos nada sobre Fafnir.",
  ui_story_5060_50600601_9_dialog_content = "É verdade. Eu pedi para algumas pessoas acessarem a rede de inteligência da Illumina para obter mais informações, mas não encontramos nada.",
  ui_story_5060_50600601_10_dialog_content = "Não há necessidade de se preocuparar. Fafnir é doga Ratclaw é in a nutshell.",
  ui_story_5060_50600601_11_dialog_content = "E quem sabe? Talvez encontremos seu último amigo desaparecido no nosso próximo endereço de entrega?",
  ui_story_5060_50600601_12_dialog_content = "Afinal, este mundo pode ser bem pequeno.",
  ui_story_5060_50600601_13_dialog_content = "Você tem razão.",
  ui_story_5060_50600601_14_dialog_content = "Texto:O que a comida",
  ui_story_5060_50600601_15_dialog_content = "Na verdade, este não é um pedido de comida. A loja gosta de agradecer aos seus clientes regulares com alguns molhos especiais, então é isso que estamos entregando.",
  ui_story_5060_50600601_16_dialog_content = "E o endereço é em... O Deserto Rediesel? Uau, que coincidência. Será que o Fafnir também aparecerá por lá?",
  ui_story_5060_50600601_17_dialog_content = "Lembra do que aqueles contrabandistas disseram? Eles arriscaram ser caçados por um dragão apenas para roubar algum tipo de tesouro dele.",
  ui_story_5060_50600601_18_dialog_content = "O dragão da coleção do leilão?",
  ui_story_5060_50600601_19_dialog_content = "Quando ouvi os contrabandistas, eu soube que eles definitivamente não estavam falando sobre Fafnir.",
  ui_story_5060_50600601_20_dialog_content = "Não importa em qual mundo ele esteja ou quem seja seu oponente, Fafnir recorrerá a qualquer meio para adquirir tesouros.",
  ui_story_5060_50600601_21_dialog_content = "Seu amigo é realmente tão assustador assim?",
  ui_story_5060_50600601_22_dialog_content = "Não se preocupe, ele é conhecido por se dar bem pacificamente com outras pessoas! Apenas não com tantas assim!",
  ui_story_5060_50600601_23_option_content = "Ainda soa um pouco assustador...",
  ui_story_5060_50600601_24_option_content = "Parece um dragão inacessível",
  ui_story_5060_50600601_25_dialog_content = "Relaxa, você está conosco, lembra? Se o pior acontecer, nós simplesmente nos uniremos contra ele!",
  ui_story_5060_50600601_26_dialog_content = "Mesmo estando com bastante medo, temos que continuar...",
  ui_story_5060_50600601_27_dialog_content = "É hora de colocar um fim a esse incidente de contrabando no leilão!",
  ui_story_5060_50600601_28_dialog_content = "Prometi o mesmo ao meu chefe. Se houver algo em que eu possa ajudar, farei o meu melhor para dar uma mão!",
  ui_story_5060_50600601_29_dialog_content = "Text: tar Contents:If necessary, the same way as the original text, and the same way,  and the same way as the original text the little bit or the first time. the text, and the same way as the original text,, and the same way as the original text, and the same way as the original text, and the same-0> can be the first time in the original text,, and the same way the first",
  ui_story_5060_50600601_30_dialog_content = "Você sabe exatamente onde encontrar este endereço, PlayerName?",
  ui_story_5060_50600601_31_dialog_content = "Estou meio familiarizado com isso. É um dos pontos fortes da Rediesel Wrench.",
  ui_story_5060_50600601_32_dialog_content = "Agora que penso nisso, provavelmente já estou atrasado para uma viagem até lá.",
  ui_story_5060_50600601_33_dialog_content = "Mesmo que vasculhem o deserto, eles também sabem como realizar comércio honesto.",
  ui_story_5060_50600601_34_dialog_content = "Mas se quisermos entrar no território deles com segurança, é melhor você deixar eu cumprimentá-los primeiro.",
  ui_story_5060_50600601_35_dialog_content = "PlayerName é super confiável.",
  ui_story_5060_50600601_36_dialog_content = "Tohru, deixe sua motocicleta com esses soldados, para que eles possam levá-la de volta ao posto avançado. Caso contrário, há uma boa chance de que esses caras da Rediesel Wrench tentem levá-la.",
  ui_story_5060_50600601_37_dialog_content = "Mesmo que geralmente dirijam seus próprios veículos, é melhor estar preparado.",
  ui_story_5060_50600601_38_dialog_content = "Não se preocupe, Srta. Tohru. Nós vamos cuidar desta moto!",
  ui_story_5060_50600601_39_dialog_content = "Para onde aqueles contrabandistas sem-vergonha se arrastaram?!",
  ui_story_5060_50600601_40_dialog_content = "Parece que os contrabandistas já cruzaram a Rediesel Wrench. Eles não devem ter medo de ninguém...",
  ui_story_5060_50600601_41_dialog_content = "Deixe-me apresentar a todos! Este é Sinsa, o atual líder da Rediesel Wrench.",
  ui_story_5060_50600601_42_dialog_content = "E aqui estão os meus amigos mais recentes!",
  ui_story_5060_50600601_43_dialog_content = "Esse cara parece realmente durão! Quer ver quem é mais forte, grandão?",
  ui_story_5060_50600601_44_dialog_content = "Desculpe, mas eu nunca bati em uma mulher na minha vida, muito menos em uma empregada.",
  ui_story_5060_50600601_45_dialog_content = "Ei, PlayerName! Você disse que sabia algo sobre esses contrabandistas fedorentos, certo? Eu não vou descansar até dar uma surra naqueles idiotas primeiro!",
  ui_story_5060_50600601_46_dialog_content = "Não me diga que esses caras roubaram algo de você?",
  ui_story_5060_50600601_47_dialog_content = "De jeito nenhum! Aqueles caras podiam ser dez vezes mais corajosos e ainda assim não teriam coragem de roubar de nós!",
  ui_story_5060_50600601_48_dialog_content = "A verdade é que esses contrabandistas costumavam ser bem discretos aqui no Deserto Rediesel.",
  ui_story_5060_50600601_49_dialog_content = "Não sei o que entrou na cabeça deles, mas ultimamente eles têm causado todo tipo de problema.",
  ui_story_5060_50600601_50_dialog_content = "Eles pareciam quase delirantes, correndo e gritando sobre monstros e \"apocalipse iminente\" ou algo assim!",
  ui_story_5060_50600601_51_dialog_content = "Eles já impactaram enormemente nossas operações diárias!",
  ui_story_5060_50600601_52_dialog_content = "Por causa deles, quase não temos caravanas de Lumópolis atravessando o deserto!",
  ui_story_5060_50600601_53_dialog_content = "Ah... Uh...",
  ui_story_5060_50600601_54_dialog_content = "Você realmente tem alguma informação sobre eles? Se tiver, desembucha logo!",
  ui_story_5060_50600601_55_dialog_content = "N-Nós íamos te pedir mais informações sobre eles.",
  ui_story_5060_50600601_56_dialog_content = "Tipo se eles perderam algum tesouro recentemente?",
  ui_story_5060_50600601_57_dialog_content = "Junte-se à Rediesel Wrench e talvez eu me sinta inclinado a te contar.",
  ui_story_5060_50600601_58_dialog_content = "Não isso de novo... Não importa, vou apenas perguntar ao Odi.",
  ui_story_5060_50600601_59_dialog_content = "Ela é quem está de olho em tudo por aqui.",
  ui_story_5060_50600601_60_dialog_content = "Você parece realmente popular, PlayerName.",
  ui_story_5060_50600601_61_dialog_content = "Ah certo, quase esqueci.",
  ui_story_5060_50600601_62_dialog_content = "Allow me to introduce more of the in front of theountry span- 1. The0 gum . . .",
  ui_story_5060_50600601_63_dialog_content = "Alguém aqui é um cliente regular do Sr. Liu? Se sim, eu tenho um molho para entregar em nome dele!",
  ui_story_5060_50600601_64_dialog_content = "Uau, nunca pensei que colocaria as mãos nessa coisa boa?! Me dê isso, rápido!",
  ui_story_5060_50600601_65_dialog_content = "Eu já fui várias vezes buscar isso; por que eu deveria deixar você ficar com isso?!",
  ui_story_5060_50600601_66_dialog_content = "São/Outras informações: São os me, são os me, os Beav Necrom of the Company: Você to ambitious:  and: . . and: a lot of people don& and: to work to be a good neighbor. Shea.0, and- to do a few days ago, in  (3  a ICY: 2013, , 2013, 2013, JK: 2013:, , but this and 1. 1  1 1, getting your own. sub  for and 4 critiquing in: 1. 2. 3 of\n\n,. 3. ,  a 1 2013 m . council Intro  a are T... \n\n<|ipynb_marker|>",
  ui_story_5060_50600601_67_dialog_content = "Parem de brigar ou vou confiscar tudo!",
  ui_story_5060_50600601_68_dialog_content = "Vamos voltar primeiro para a fortaleza da Rediesel Wrench. Vamos lá, PlayerName; você e seus amigos podem vir comigo.",
  ui_story_5060_50600601_69_dialog_content = "O resto de vocês pode me seguir no outro carro!",
  ui_story_5060_50600601_70_dialog_content = "Coisa certa.",
  ui_story_5060_50600601_71_dialog_content = "Tudo bem, amigos! Hora de experimentar a velocidade e emoção da Rediesel Wrench!",
  ui_story_5060_50600601_72_dialog_content = "Agora segure firme!",
  ui_story_5060_50600601_73_dialog_content = "<size=45>Decolar!</size>",
  ui_story_5060_50600601_74_dialog_content = "Uau! Que maneira incrível de dirigir!",
  ui_story_5060_50600601_75_dialog_content = "Você está bem, Kanna?",
  ui_story_5060_50600601_76_dialog_content = "Estou bem. Que legal!",
  ui_story_5060_50600601_77_dialog_content = "Isso é bom, mas parece que algo está errado com PlayerName!",
  ui_story_5060_50600601_78_dialog_content = "Você não está sentindo enjoo de carro, está?",
  ui_story_5060_50600601_79_dialog_content = "Um piloto de Colossus nunca poderia ficar enjoado em um carro!",
  ui_story_5060_50600601_80_dialog_content = "Sabe que não é bom se esforçar demais, né?",
  ui_story_5060_50600601_81_dialog_content = "Apenas apoie-se em mim e tudo ficará bem!",
  ui_story_5060_50600601_82_dialog_content = "N... Não, obrigado.",
  ui_story_5060_50600601_83_dialog_content = "Você sentiu a velocidade e emoção da Rediesel Wrench?",
  ui_story_5060_50600601_84_dialog_content = "A próxima parte vai ser um pouco instável, então tente não ser derrubado!",
  ui_story_5060_50600601_85_dialog_content = "Antes de conhecer você, eu não conseguia parar de imaginar como era a Rediesel Wrench.",
  ui_story_5060_50600601_86_dialog_content = "Afinal, PlayerName disse que você era do tipo que pegaria minha motocicleta à força!",
  ui_story_5060_50600601_87_dialog_content = "Achei que vocês seriam um bando de arruaceiros com péssimas atitudes...",
  ui_story_5060_50600601_88_dialog_content = "Mas agora vejo que estava errado em pensar isso.",
  ui_story_5060_50600601_89_dialog_content = "Hahaha, não se preocupe com isso! Todos nós cometemos erros de vez em quando!",
  ui_story_5060_50600601_90_dialog_content = "Mas, desde que falemos abertamente e confiemos um no outro, sempre seremos amigos correndo por este deserto louco!",
  ui_story_5060_50600601_91_dialog_content = "A Rediesel Wrench é toda sobre liberdade!",
  ui_story_5060_50600601_92_dialog_content = "Um pouco de liberdade demais, se você me perguntar—",
  ui_story_5060_50600801_1_dialog_content = "Eu me sinto tonto.",
  ui_story_5060_50600801_2_dialog_content = "Realmente tonto.",
  ui_story_5060_50600801_3_dialog_content = "Venha aqui, Kanna. Deixe-me te abraçar.",
  ui_story_5060_50600801_4_dialog_content = "Eu não achei que você seria o único a ficar enjoado no final.",
  ui_story_5060_50600801_5_dialog_content = "Não tem jeito; afinal, ela ainda é tão jovem e tenho certeza de que esta é a primeira vez dela em um passeio tão turbulento.",
  ui_story_5060_50600801_6_dialog_content = "Enfim, estou começando a ficar com um pouco de fome. Quando podemos comer?",
  ui_story_5060_50600801_7_dialog_content = "Você ficou calado todo esse tempo porque não queria ficar com fome de tanto falar, né?",
  ui_story_5060_50600801_8_dialog_content = "N-Não! Eu estive sempre atento aos Eclipsitas!",
  ui_story_5060_50600801_9_dialog_content = "Derrubamos um monte deles mais cedo. Você poderia ter comido quantos quisesse.",
  ui_story_5060_50600801_10_dialog_content = "Como eu poderia comer algo assim?!",
  ui_story_5060_50600801_11_dialog_content = "Bem, e os doces que aqueles soldados Illuminan te deram?",
  ui_story_5060_50600801_12_dialog_content = "Esses são um símbolo da nossa camaradagem!",
  ui_story_5060_50600801_13_dialog_content = "Estou planejando levar esses de volta para casa conosco! Não vai significar nada se eu comê-los agora!",
  ui_story_5060_50600801_14_dialog_content = "Ah, esquece... Toma. O Sr. Liu me deu alguns a mais, mas não consigo comer todos.",
  ui_story_5060_50600801_15_dialog_content = "Você realmente é um bom amigo, Tohru!",
  ui_story_5060_50600801_16_dialog_content = "G-Saia de cima de mim!",
  ui_story_5060_50600801_17_dialog_content = "Por terem sobrevivido a uma batalha tão intensa há pouco tempo, vocês dois estão realmente cheios de energia.",
  ui_story_5060_50600801_18_dialog_content = "Você está falando daqueles Eclipsitas no deserto? Lidar com essas pragas não é nada para alguém como eu!",
  ui_story_5060_50600801_19_dialog_content = "Ainda assim, quando finalmente chegamos ao deserto, eu pensei que haveria bem menos deles aqui.",
  ui_story_5060_50600801_20_dialog_content = "Então, por que ainda existem tantos Eclipsitas?",
  ui_story_5060_50600801_21_dialog_content = "Se há uma coisa que não falta neste mundo, são Eclipsitas. Onde quer que você encontre Aurorianos, esses monstros nunca estarão muito longe—",
  ui_story_5060_50600801_22_dialog_content = "Mas até lugares sem Aurorianos estão infestados de Eclipsitas!",
  ui_story_5060_50600801_23_dialog_content = "Bem, graças ao amplo sistema de vigilância do Odi, podemos rastrear a maioria dos movimentos deles e nos preparar adequadamente.",
  ui_story_5060_50600801_24_dialog_content = "Isso também ajuda você a defender suas fortalezas do exército de Lumópolis, certo?",
  ui_story_5060_50600801_25_dialog_content = "Hahaha! Direto como sempre, PlayerName! É isso que eu gosto em você!",
  ui_story_5060_50600801_26_dialog_content = "Tudo bem, Odi deve estar lá dentro. Pergunte a ela o que você quiser.",
  ui_story_5060_50600801_27_dialog_content = "Odi—",
  ui_story_5060_50600801_28_dialog_content = "Hã? Quem é a pessoa ao lado dela?",
  ui_story_5060_50600801_29_dialog_content = "Você é bem bom, <color=#FFB400>Fafnir</color>, mas se quiser me vencer...",
  ui_story_5060_50600801_30_dialog_content = "Você ainda tem um longo caminho pela frente!",
  ui_story_5060_50600801_31_dialog_content = "Pegue isso—",
  ui_story_5060_50600801_32_dialog_content = "<size=45>Perfurador-est</size>",
  ui_story_5060_50600801_33_dialog_content = "Espere, não use esse movimento!",
  ui_story_5060_50600801_34_dialog_content = "...",
  ui_story_5060_50600801_35_dialog_content = "Fafnir parecia tão ferido; ele nem mesmo nos cumprimentou quando entramos.",
  ui_story_5060_50600801_36_dialog_content = "Ei Fafnir, ainda está vivo?",
  ui_story_5060_50600801_37_dialog_content = "Acho que a alma dele já deixou o corpo. Ele deve ter perdido muito feio.",
  ui_story_5060_50600801_38_dialog_content = "Eu não perdi. Apenas não estou de bom humor, só isso.",
  ui_story_5060_50600801_39_dialog_content = "Há quanto tempo, PlayerName! Você trouxe esses novos amigos para jogar hoje?",
  ui_story_5060_50600801_40_dialog_content = "Sim. E eles também acontecem de ser amigos de Fafnir.",
  ui_story_5060_50600801_41_dialog_content = "(Então este é o Fafnir... Ele tem um olhar tão feroz nos olhos.)",
  ui_story_5060_50600801_42_dialog_content = "(Em um momento como este, uma saudação amigável parece extremamente importante para diminuir a distância entre nós.)",
  ui_story_5060_50600801_43_dialog_content = "Ei, Faffy! Meu nome é PlayerName e eu sou um dos Tohru...",
  ui_story_5060_50600801_44_dialog_content = "Não me trate por um nome tão informal.",
  ui_story_5060_50600801_45_dialog_content = "Er... De qualquer forma, viemos aqui para pedir um pouco de informação ao Odi.",
  ui_story_5060_50600801_46_dialog_content = "Contanto que você não me peça para me juntar à Rediesel Wrench, aceitaremos quaisquer condições que você tenha para nós.",
  ui_story_5060_50600801_47_dialog_content = "\"Condições\"? Eu não me importo com isso! Eu simplesmente derrotei esse cara trezentas vezes seguidas, então estou de ótimo humor!",
  ui_story_5060_50600801_48_dialog_content = "Correção: foram duzentas e noventa e nove vezes.",
  ui_story_5060_50600801_49_dialog_content = "Eh, está perto o suficiente. De qualquer forma, vou te ajudar de graça desta vez.",
  ui_story_5060_50600801_50_dialog_content = "(Obrigado, <size=45>Faffy!</size>)",
  ui_story_5060_50600801_51_dialog_content = "Preciso da sua ajuda para encontrar algumas filmagens relacionadas a um grupo de contrabandistas. Posso mostrar-lhe mais ou menos para qual direção eles estavam indo...",
  ui_story_5060_50600801_52_dialog_content = "Então você estava com a Rediesel Wrench todo esse tempo, Fafnir?",
  ui_story_5060_50600801_53_dialog_content = "Você é um dragão que acumula tesouros, mas, julgando pela natureza deles... É claro que a Rediesel Wrench é um grupo de caçadores de tesouros.",
  ui_story_5060_50600801_54_dialog_content = "Sinceramente, estou surpreso que você tenha ficado por tanto tempo...",
  ui_story_5060_50600801_55_dialog_content = "Eles te subornaram com um fornecimento vitalício de doces ou algo assim?!",
  ui_story_5060_50600801_56_dialog_content = "Fafnir não é um glutão insaciável como você, Elma.",
  ui_story_5060_50600801_57_dialog_content = "Contanto to  and Par\n\n--Cont > has been.",
  ui_story_5060_50600801_58_dialog_content = "Não tem absolutamente nada a ver com profissão, status ou valor na sociedade.",
  ui_story_5060_50600801_59_dialog_content = "Onde você está indo, Fafnir?",
  ui_story_5060_50600801_60_dialog_content = "Vou sair para tomar um ar.",
  ui_story_5060_50600801_61_dialog_content = "Como pude perder tão miseravelmente? Onde foi que eu errei?",
  ui_story_5060_50600801_62_dialog_content = "Será uma questão de força de vontade?",
  ui_story_5060_50600802_1_dialog_content = "O que você quer? Ainda estou pensando em uma maneira de derrotar Odi.",
  ui_story_5060_50600802_2_dialog_content = "Não se preocupe, você terá todo o tempo do mundo para pensar nisso mais tarde.",
  ui_story_5060_50600802_3_dialog_content = "Apenas volte para dentro por enquanto. Odi tem algo para te contar.",
  ui_story_5060_50600802_4_dialog_content = "Hmph... Tenho certeza de que ela só quer se gabar das vitórias dela.",
  ui_story_5060_50600802_5_dialog_content = "Odeio admitir isso, mas no momento... Ela é melhor do que eu.",
  ui_story_5060_50600802_6_dialog_content = "É melhor você cuidar do seu tom de voz.",
  ui_story_5060_50600802_7_dialog_content = "Se você for longe demais, eu posso acabar te amaldiçoando até virar pó.",
  ui_story_5060_50600802_8_dialog_content = "Que diabos ele está falando?",
  ui_story_5060_50600802_9_dialog_content = "Não ligue para ele, ele só gosta de parecer ousado!",
  ui_story_5060_50600802_10_dialog_content = "Você saiu correndo tão rápido agora há pouco que eu não tive tempo de te dar meu presente.",
  ui_story_5060_50600802_11_dialog_content = "Seu presente. Para mim?",
  ui_story_5060_50600802_12_dialog_content = "Aqui está, a versão mais recente desta máquina de jogo.",
  ui_story_5060_50600802_13_dialog_content = "Anime-se, Fafnir! Minhas mãos geniais construíram isso do zero, o que torna tão valioso quanto qualquer tesouro!",
  ui_story_5060_50600802_14_dialog_content = "Então você não vai me humilhar?",
  ui_story_5060_50600802_15_dialog_content = "Humilhar você? Não há mais necessidade disso. Além disso, eu reconheci você como um oponente digno há muito tempo.",
  ui_story_5060_50600802_16_dialog_content = "Mesmo um viciado em jogos como Gronru não conseguiu me fornecer os dados de teste que eu precisava com esta máquina de jogo.",
  ui_story_5060_50600802_17_dialog_content = "Você é a primeira e única pessoa a enfrentar trezentos rounds contra mim, e eu não poderia estar mais grato por isso!",
  ui_story_5060_50600802_18_dialog_content = "Tudo bem, agora é hora de lidar com o pedido de PlayerName.",
  ui_story_5060_50600802_19_dialog_content = "Posso perguntar como você planeja fazer isso?",
  ui_story_5060_50600802_20_dialog_content = "É simples! Primeiro, vou fazer com que o sistema de vigilância realize uma busca automática e, em seguida, compararei as imagens obtidas.",
  ui_story_5060_50600802_21_dialog_content = "Sim... eu não entendo como isso funciona. Esqueça que perguntei.",
  ui_story_5060_50600802_22_dialog_content = "E quanto tempo vai levar?",
  ui_story_5060_50600802_23_dialog_content = "Cerca de vinte minutos.",
  ui_story_5060_50600802_24_dialog_content = "Por que você está andando de um lado para o outro todo esse tempo, Fafnir? Deixe-me adivinhar, você está planejando dar Odi aquele livro em suas mãos como um presente?",
  ui_story_5060_50600802_25_dialog_content = "Isso não é da conta de vocês.",
  ui_story_5060_50600802_26_dialog_content = "Vamos ver que tipo de livro é esse.",
  ui_story_5060_50600802_27_dialog_content = "Ah cara, não esse seu livro estúpido de maldições de novo!",
  ui_story_5060_50600802_28_dialog_content = "A senhorita Odi tem uma sede insaciável por conhecimento! Se ela colocasse os olhos neste livro, quem sabe o que aconteceria?!",
  ui_story_5060_50600802_29_dialog_content = "Por que.",
  ui_story_5060_50600802_30_dialog_content = "Aff.",
  ui_story_5060_50600802_31_dialog_content = "Isso me lembra, também devemos dar aos nossos novos amigos da Rediesel Wrench alguns presentes comemorativos!",
  ui_story_5060_50600802_32_dialog_content = "Ah, Senhorita Tohru?",
  ui_story_5060_50600802_33_dialog_content = "Por que você... Continua me encarando assim? Tem algo grudado na minha cauda?",
  ui_story_5060_50600802_34_dialog_content = "De forma alguma! Eu estava apenas pensando que com uma cauda grande e maravilhosa como a sua... Você ficaria realmente linda em uma fantasia de donzela, Maggie!",
  ui_story_5060_50600802_35_dialog_content = "Já pensou em entrar no mundo das empregadas?",
  ui_story_5060_50600802_36_dialog_content = "Aposto que Kobayashi ficaria super animada se te visse em uma fantasia de empregada também!",
  ui_story_5060_50600802_37_dialog_content = "Aqui, experimente por si mesmo!",
  ui_story_5060_50600802_38_dialog_content = "Soluço, soluço, soluço—",
  ui_story_5060_50600802_39_dialog_content = "Barbara, Regina, salvem-meeee—",
  ui_story_5060_50600802_40_dialog_content = "Vocês dois têm vozes tão únicas para cantar! Só queria que o Shouta estivesse aqui para ouvir também.",
  ui_story_5060_50600802_41_dialog_content = "Hahaha! Bem, a música é feita para ser compartilhada e apreciada por todos!",
  ui_story_5060_50600802_42_dialog_content = "Soluço, soluço, soluço—",
  ui_story_5060_50600802_43_dialog_content = "B-Brock, por favor me ajude...",
  ui_story_5060_50600802_44_dialog_content = "Ei Kanna, você sabia?",
  ui_story_5060_50600802_45_dialog_content = "Na verdade, eu sou o verdadeiro chefe da Rediesel Wrench!",
  ui_story_5060_50600802_47_dialog_content = "Uau—",
  ui_story_5060_50600802_48_dialog_content = "Um chefe secreto. Isso é tão legal.",
  ui_story_5060_50600802_49_dialog_content = "Ele também é completamente inútil...",
  ui_story_5060_50600802_50_dialog_content = "E-E-Então vou perguntar ao Jomu! Com certeza o Jomu vai me salvar!",
  ui_story_5060_50600802_51_dialog_content = "Você está de olho na minha seleção de comidas há um bom tempo, minha bela e jovem convidada! Você deve sofrer de uma séria indecisão na hora de comprar, não é?",
  ui_story_5060_50600802_52_dialog_content = "Então, por que não te apresento o meu mais recente produto especial: a Caixa Misteriosa de Sobremesas!",
  ui_story_5060_50600802_53_dialog_content = "Cada caixa contém um tipo diferente de sobremesa.",
  ui_story_5060_50600802_54_dialog_content = "Em outras palavras, cada caixa contém um futuro que pertence a você e mais ninguém!",
  ui_story_5060_50600802_55_dialog_content = "Além disso, estou com uma promoção muito especial agora, e uma única Caixa Misteriosa vai custar apenas 2.000 Noitium! É uma pechincha por esse preço!",
  ui_story_5060_50600802_56_dialog_content = "Vou levar todos eles!!!",
  ui_story_5060_50600802_57_dialog_content = "Ah, não seja tímido! Eu posso até usar escamas para fazer um traje de empregada sob medida especialmente para você, Maggie!",
  ui_story_5060_50600802_58_dialog_content = "Tudo que eu peço é que você tire uma foto comigo depois!",
  ui_story_5060_50600802_59_dialog_content = "N-N-N-Não, por favor—",
  ui_story_5060_50600802_60_dialog_content = "Líder! Voltei da minha caçada e consegui uma grande quantidade de presas hoje!",
  ui_story_5060_50600802_61_dialog_content = "Também desenterrei um monte de aranhas da areia. Dê uma olhada.",
  ui_story_5060_50600802_62_dialog_content = "Qual é o motivo de tantos rostos desconhecidos, chefe? Esses caras são convidados?",
  ui_story_5060_50600802_63_dialog_content = "Vou te apresentar em um minuto. Só vá deixar a comida na cozinha primeiro.",
  ui_story_5060_50600802_64_dialog_content = "...",
  ui_story_5060_50600802_65_dialog_content = "Ah! Aquela garotinha acabou de comer todas as aranhas de areia que eu trabalhei tanto para desenterrar!!!",
  ui_story_5060_50600802_66_dialog_content = "Hum. Estavam gostosos.",
  ui_story_5060_50600802_67_dialog_content = "Kanna! Não coma as coisas dos outros sem pedir permissão primeiro!",
  ui_story_5060_50600802_68_dialog_content = "Ah. Desculpe.",
  ui_story_5060_50600802_69_dialog_content = "Você é bem corajosa, garotinha! Não acredito que você comeu todas essas aranhas de areia cruas!",
  ui_story_5060_50600802_70_dialog_content = "Além do nosso chefe e do Brock, você é definitivamente a primeira pessoa que vejo fazer algo assim!",
  ui_story_5060_50600802_71_dialog_content = "Gosto muito: Delícia.",
  ui_story_5060_50600802_72_dialog_content = "Sinceramente... Quantas vezes Kobayashi já te disse para parar de colocar tudo na boca?",
  ui_story_5060_50600802_73_dialog_content = "Ai...",
  ui_story_5060_50600802_74_dialog_content = "Eu me pergunto como a Kobayashi está indo em seu mundo. Será que ela está preocupada comigo agora?",
  ui_story_5060_50600802_75_dialog_content = "Aqui, senhorita Tohru. Tome um pouco de água.",
  ui_story_5060_50600802_76_dialog_content = "...",
  ui_story_5060_50600802_77_dialog_content = "Qual o problema, não gosta de água do deserto?",
  ui_story_5060_50600802_78_dialog_content = "Não é isso.",
  ui_story_5060_50600802_79_dialog_content = "Essa cena quente e aconchegante me lembrou da Kobayashi.",
  ui_story_5060_50600802_80_dialog_content = "Não voltei depois de todo esse tempo. Ela provavelmente está doente de preocupação comigo...",
  ui_story_5060_50600802_81_dialog_content = "Consegui encontrar todos, mas ainda não temos como voltar ao nosso mundo... Suspiro.",
  ui_story_5060_50600802_82_dialog_content = "É, PlayerName me contou tudo sobre a situação de vocês.",
  ui_story_5060_50600802_83_dialog_content = "Então você é realmente de outro mundo, hein? Se qualquer outra pessoa me dissesse isso, eu não acreditaria nem por um segundo.",
  ui_story_5060_50600802_84_dialog_content = "PlayerName diz que vocês só precisam encontrar um lugar onde o mana não seja tão instável, e vocês podem ir para casa. Isso está certo?",
  ui_story_5060_50600802_85_dialog_content = "Na verdade, o mana aqui no Deserto Rediesel deve ser estável o suficiente para ser usado.",
  ui_story_5060_50600802_86_dialog_content = "Mas eu tentei há um tempo atrás e ainda não consigo ativar o portal corretamente. Talvez eu ainda precise de mais poder.",
  ui_story_5060_50600802_87_dialog_content = "E se eu não conseguir fazer funcionar, então os outros com certeza...",
  ui_story_5060_50600802_88_dialog_content = "Desculpe.",
  ui_story_5060_50600802_89_dialog_content = "Todos vocês têm seus próprios problemas, mas ainda estão me ajudando a resolver este caso de contrabando.",
  ui_story_5060_50600802_90_dialog_content = "Tudo bem! Queremos ajudar, sabe.",
  ui_story_5060_50600802_91_dialog_content = "Afinal, somos amigos agora. Não somos?",
  ui_story_5060_50600802_92_dialog_content = "Isso mesmo! Você também é um amigo da Chave Rediesel in a passo ou de Red, já que você e PlayerName nos nos ajudaram a eliminar todos esses Eclipsitasas, &oz, eggheads to the E. It’s a great time to be!  A lot of FB, the Rediesel Wrench.",
  ui_story_5060_50600802_93_dialog_content = "Vamos ajudar vocês a encontrar uma solução!",
  ui_story_5060_50600802_94_dialog_content = "É... tenho certeza que também encontraremos um caminho de volta.",
  ui_story_5060_50600802_95_dialog_content = "E quando fizermos isso, com certeza vou contar tudo sobre nossa aventura para Kobayashi! Então, quando finalmente voltarmos a visitar este mundo novamente...",
  ui_story_5060_50600802_96_dialog_content = "Quando voltarmos para visitar novamente...",
  ui_story_5060_50600802_97_dialog_content = "Senhorita Tohru...",
  ui_story_5060_50600802_98_dialog_content = "É pura coincidência que viemos ao seu mundo desta vez.",
  ui_story_5060_50600802_99_dialog_content = "Mas na próxima vez... se tivermos sorte o suficiente para voltar novamente...",
  ui_story_5060_50600802_100_dialog_content = "Ninguém sabe o que vai acontecer no futuro, então não adianta pensar muito nisso agora.",
  ui_story_5060_50600802_101_dialog_content = "Isso mesmo, Tohru! Vamos comer primeiro!",
  ui_story_5060_50600802_102_dialog_content = "Realmente sinto inveja de você às vezes. Tudo o que você precisa fazer é comer o suficiente todos os dias para ser feliz.",
  ui_story_5060_50600802_103_dialog_content = "Mas dessa vez, você está certo...",
  ui_story_5060_50600802_104_dialog_content = "Devemos comer primeiro.",
  ui_story_5060_50600802_105_dialog_content = "Vou preparar os ingredientes!",
  ui_story_5060_50600802_106_dialog_content = "Aqui está! Um prato de insetos apimentados ao estilo Rediesel!",
  ui_story_5060_50600802_107_dialog_content = "Legal! Essa comida é perfeita para a Rediesel Wrench! Vou torná-la um prato regular para nós!",
  ui_story_5060_50600802_108_dialog_content = "Anote, Maggie! Você deve tentar se tornar uma empregada incrível, assim como Tohru!",
  ui_story_5060_50600802_109_dialog_content = "Hã?",
  ui_story_5060_50600802_110_dialog_content = "<size=45>O quê?!</size>",
  ui_story_5060_50600802_111_dialog_content = "Ainda tem algum sobrando? Eu também quero!",
  ui_story_5060_50600802_112_dialog_content = "Eu poderia definitivamente ganhar uma fortuna vendendo isso.",
  ui_story_5060_50600802_113_dialog_content = "Você tem algum tempo livre, Srta. Tohru? Você se importaria de compartilhar a receita comigo?",
  ui_story_5060_50600802_114_dialog_content = "Vou te dar 10.000 Nightium por isso.",
  ui_story_5060_50600802_115_dialog_content = "Estou cheio. Agora estou com sono.",
  ui_story_5060_50600802_116_dialog_content = "Aqui Kanna, você pode descansar nas minhas pernas.",
  ui_story_5060_50600802_117_dialog_content = "Deveria comer algo também para recuperar energia. A busca deve terminar a qualquer momento.",
  ui_story_5060_50600802_118_dialog_content = "Sabe, a comida aqui é realmente única. Talvez isso seja útil para tratar a dor nas costas de Kobayashi?",
  ui_story_5060_50600802_119_dialog_content = "Aposto que ela não vai tocar em nada disso.",
  ui_story_5060_50600802_120_dialog_content = "Você deveria tirar mais algumas fotos e levá-las de volta para ela.",
  ui_story_5060_50600802_121_dialog_content = "Você tem razão. Então você consegue dizer algumas coisas sensatas de vez em quando, né?",
  ui_story_5060_50600802_122_dialog_content = "Ei—",
  ui_story_5060_50600901_1_dialog_content = "Como esperado, nada escapa de um hacker genial como eu!",
  ui_story_5060_50600901_2_dialog_content = "Encontrei algumas filmagens desses contrabandistas sendo atacados.",
  ui_story_5060_50600901_3_dialog_content = "E parece que eles deixaram cair o que estavam transportando lá.",
  ui_story_5060_50600901_4_dialog_content = "Eles foram atacados?",
  ui_story_5060_50600901_5_dialog_content = "Eles estavam mentindo o tempo todo. Idiotas.",
  ui_story_5060_50600901_6_dialog_content = "Esses perversos violadores da ordem devem ser esmagados pelo punho de ferro da justiça!",
  ui_story_5060_50600901_7_dialog_content = "Então o tesouro perdido não tem nada a ver com a Guilda Cloudrover? Parece que a Senhora Sheol pode ficar tranquila agora.",
  ui_story_5060_50600901_8_dialog_content = "De qualquer forma, vamos lá fora dar uma olhada primeiro.",
  ui_story_5060_50600901_9_dialog_content = "...",
  ui_story_5060_50600901_10_dialog_content = "Já devemos ter perdido aquele cara até agora, certo...",
  ui_story_5060_50600901_11_dialog_content = "O-O que é isso?! Nunca vi uma criatura assim antes!",
  ui_story_5060_50600901_12_dialog_content = "Qual é o alvoroço, hein?!",
  ui_story_5060_50600901_13_dialog_content = "Somos contrabandistas experientes que já vimos o mundo.",
  ui_story_5060_50600901_14_dialog_content = "É provável que um 3, um,,sobre o que-1-1-1-1- 3 dialzinho, o agon rein the desert dragon..!",
  ui_story_5060_50600901_15_dialog_content = "Hahaha, com certeza nós o perdemos agora!",
  ui_story_5060_50600901_16_dialog_content = "Chefe, por favor pare de rir.",
  ui_story_5060_50600901_17_dialog_content = "Lembra da última vez que você riu alto? Fomos atacados por Eclipsitas imediatamente...",
  ui_story_5060_50600901_18_dialog_content = "Sério? Você deve estar lembrando errado! Hahaha!",
  ui_story_5060_50600901_19_dialog_content = "Nããããão! Isso é ruim—!",
  ui_story_5060_50600901_20_dialog_content = "A-atrás de nós! Aquele cara está bem na nossa cola!",
  ui_story_5060_50600901_21_dialog_content = "...",
  ui_story_5060_50600901_22_dialog_content = "Líder, qual é o plano?",
  ui_story_5060_50600901_23_dialog_content = "Que tal deixar o carro e dar uma corrida?",
  ui_story_5060_50600901_24_dialog_content = "Seu idiota!",
  ui_story_5060_50600901_25_dialog_content = "Você quer ser motivo de, sendo?",
  ui_story_5060_50600901_26_dialog_content = "Passamos por maus bocados e enfrentamos muitas dificuldades para conseguir aquele tesouro!",
  ui_story_5060_50600901_27_dialog_content = "Não é apenas um <color=#FFB400>ovo</color>...",
  ui_story_5060_50600901_28_dialog_content = "Umbraton está cheio de tesouros, então acho que este provavelmente não é um grande negócio.",
  ui_story_5060_50600901_29_dialog_content = "Seu idiota sem noção! Isso é um <color=#FFB400>Ovo de Dragão</color>!",
  ui_story_5060_50600901_30_dialog_content = "Chefe, aquele cara está se aproximando!",
  ui_story_5060_50600901_31_dialog_content = "Pise fundo! Aceleração total! Vamos nessa!",
  ui_story_5060_50600901_32_dialog_content = "Assim que tirarmos este ovo do deserto e entregá-lo nas mãos do contato, nosso trabalho estará concluído!",
  ui_story_5060_50600901_33_dialog_content = "Chefe, cuidado!",
  ui_story_5060_50600901_34_dialog_content = "Mortais.",
  ui_story_5060_50600901_35_dialog_content = "Que completamente tolo.",
  ui_story_5060_50600901_36_dialog_content = "Passamos por tantos problemas para pegar o ovo daquele dragão! E agora, ele...",
  ui_story_5060_50600901_37_dialog_content = "Volte e diga ao seu líder:",
  ui_story_5060_50600901_38_dialog_content = "Nunca mais roube de um dragão.",
  ui_story_5060_50600901_39_dialog_content = "Este é o seu único aviso.",
  ui_story_5060_50600901_40_dialog_content = "Na próxima vez, nem mesmo seus ossos permanecerão neste mundo.",
  ui_story_5060_50600901_41_dialog_content = "Não é possível...",
  ui_story_5060_50600901_42_dialog_content = "Mas como...?",
  ui_story_5060_50600901_43_dialog_content = "Oh meu, que reviravolta inesperada!",
  ui_story_5060_50600901_44_dialog_content = "Derrotar esse chefe final não será fácil.",
  ui_story_5060_50600901_45_dialog_content = "Tohru, você está...",
  ui_story_5060_50600901_46_dialog_content = "Vocês estão bem?",
  ui_story_5060_50600901_47_dialog_content = "Essa pessoa também é do seu mundo?",
  ui_story_5060_50600901_48_dialog_content = "Sim.",
  ui_story_5060_50600901_49_dialog_content = "Esse é o pai de Tohru, bem como o líder da Facção do Caos: Damocles, o <color=#FFB400>Imperador do Fim</color>.",
  ui_story_5060_50601001_1_dialog_content = "Entendi. Tudo faz muito mais sentido agora.",
  ui_story_5060_50601001_2_dialog_content = "O pai de Tohru descobriu os contrabandistas tentando roubar aquele ovo de dragão, e acabou ficando em sua posse.",
  ui_story_5060_50601001_3_dialog_content = "Então, para evitar serem punidos por seu líder, os contrabandistas tentaram jogar a culpa em outras pessoas.",
  ui_story_5060_50601001_4_dialog_content = "Pai…",
  ui_story_5060_50601001_5_dialog_content = "Então ele também está neste mundo...",
  ui_story_5060_50601001_6_dialog_content = "Espere um minuto, ele pode ser capaz de—",
  ui_story_5060_50601001_7_dialog_content = "Ei! Você não está prestes a fazer algo estúpido de novo, está?!",
  ui_story_5060_50601001_8_dialog_content = "Mas eu não disse nada!",
  ui_story_5060_50601001_9_dialog_content = "Depois de todos esses anos, você ainda acha que eu não sei o que está em sua mente?",
  ui_story_5060_50601001_10_dialog_content = "Você estava claramente prestes a perguntar ao Imperador do Fim se poderia voltar a este mundo novamente!",
  ui_story_5060_50601001_11_dialog_content = "Afinal, se alguém pode fazer isso, é ele.",
  ui_story_5060_50601001_12_dialog_content = "...",
  ui_story_5060_50601001_13_dialog_content = "Você tem razão.",
  ui_story_5060_50601001_14_dialog_content = "Ele definitivamente veio aqui para me buscar, mas se eu for com ele agora, ele nunca me deixará voltar para este mundo.",
  ui_story_5060_50601001_15_dialog_content = "Você e os outros não querem voltar também, Elma?!",
  ui_story_5060_50601001_16_dialog_content = "Entendo. Sei que não podemos ficar aqui por muito tempo, já que a presença de dragões vai perturbar a ordem natural deste mundo...",
  ui_story_5060_50601001_17_dialog_content = "Mas ainda podemos reservar bastante tempo para experimentar toda a maravilhosa comida que temos à disposição!",
  ui_story_5060_50601001_18_dialog_content = "Este mundo é muito divertido. Seria uma pena se nunca pudéssemos voltar!",
  ui_story_5060_50601001_19_dialog_content = "Quero ver aquela garota de novo.",
  ui_story_5060_50601001_20_dialog_content = "E eu ainda não derrotei aquela mulher.",
  ui_story_5060_50601001_21_dialog_content = "Sair assim seria o mesmo que fugir. Eu me recuso a fazer algo tão vergonhoso.",
  ui_story_5060_50601001_22_dialog_content = "Seu pai realmente não está disposto a ouvir, Srta. Tohru?",
  ui_story_5060_50601001_23_dialog_content = "Para os dragões, o poder é tudo.",
  ui_story_5060_50601001_24_dialog_content = "Agora, não sou forte o suficiente para derrotar meu pai...",
  ui_story_5060_50601001_25_dialog_content = "Isso significa que não tenho como convencê-lo a aceitar meus desejos...",
  ui_story_5060_50601001_26_dialog_content = "Mas mesmo assim, isso não significa que eu não deva tentar! Mesmo que haja apenas um pequeno vislumbre de esperança, me recuso a desistir tão facilmente!",
  ui_story_5060_50601001_27_dialog_content = "<color=#e8d9bb>Desfiladeiro Chama Carmesim</color>",
  ui_story_5060_50601001_28_dialog_content = "Este deve ser o lugar.",
  ui_story_5060_50601001_29_dialog_content = "Olha, o ovo de dragão que o Imperador do Fim recuperou está naquela caverna ali.",
  ui_story_5060_50601001_30_dialog_content = "Vocês não disseram uma palavra esse tempo todo.",
  ui_story_5060_50601001_31_dialog_content = "Será que...",
  ui_story_5060_50601001_32_dialog_content = "Ele também está aqui.",
  ui_story_5060_50601001_33_dialog_content = "Nossa, que presença assustadora!",
  ui_story_5060_50601001_34_dialog_content = "Estou feliz que você decidiu se revelar, Tohru.",
  ui_story_5060_50601001_35_dialog_content = "Pai.",
  ui_story_5060_50601001_36_dialog_content = "Venha. Estamos saindo.",
  ui_story_5060_50601001_37_dialog_content = "O portal pode ser usado a qualquer momento.",
  ui_story_5060_50601001_38_dialog_content = "Sabia...",
  ui_story_5060_50601001_39_dialog_content = "Mesmo com os baixos níveis de mana deste mundo, você não tem problemas para ativar o portal.",
  ui_story_5060_50601001_40_dialog_content = "...",
  ui_story_5060_50601001_41_dialog_content = "Pai! Posso falar com você sobre algo?!",
  ui_story_5060_50601001_42_dialog_content = "Muito bem, desde que não seja algo sem sentido.",
  ui_story_5060_50601001_43_dialog_content = "Eu sei que você veio aqui porque percebeu algo errado com o meu próprio portal.",
  ui_story_5060_50601001_44_dialog_content = "E eu também quero voltar ao mundo de Kobayashi com você.",
  ui_story_5060_50601001_45_dialog_content = "É apenas...",
  ui_story_5060_50601001_46_dialog_content = "De vez em quando... Tudo bem se eu voltar para visitar este mundo?",
  ui_story_5060_50601001_47_dialog_content = "Não.",
  ui_story_5060_50601001_48_dialog_content = "Mas você está disposto a me deixar viver no mundo de Kobayashi!",
  ui_story_5060_50601001_49_dialog_content = "Não me lembro de concordar com isso.",
  ui_story_5060_50601001_50_dialog_content = "Além disso, os habitantes deste mundo são muito semelhantes aos humanos do nosso mundo.",
  ui_story_5060_50601001_51_dialog_content = "Roubo, engano, preconceito e brigas internas são muito comuns aqui.",
  ui_story_5060_50601001_52_dialog_content = "Um número dessas pessoas também possui habilidades extraordinárias, que podem ter uma influência profunda em nós como dragões.",
  ui_story_5060_50601001_53_dialog_content = "Permanecer neste mundo resultará em apenas uma das duas coisas para você:",
  ui_story_5060_50601001_54_dialog_content = "Um, sua presença continuará a desgastar os princípios que governam este mundo.",
  ui_story_5060_50601001_55_dialog_content = "4-5@@... 4 boot camp- 2- ä- 1- 1 on the web.",
  ui_story_5060_50601001_56_dialog_content = "...",
  ui_story_5060_50601001_57_dialog_content = "Desculpe, mas posso dizer algumas palavras?",
  ui_story_5060_50601001_58_dialog_content = "Meu nome é PlayerName e estou viajando com Tohru durante a maior parte do tempo dela aqui.",
  ui_story_5060_50601001_59_dialog_content = "É um prazer conhecê-lo, Sr. Imperador do Fim! Também estou muito grato a você por recuperar aquele ovo de dragão roubado.",
  ui_story_5060_50601001_60_dialog_content = "Eu não tinha intenção de quebrar as regras deste mundo.",
  ui_story_5060_50601001_61_dialog_content = "Mas aqueles ladrões não conheciam o significado de medo nem de satisfação.",
  ui_story_5060_50601001_62_dialog_content = "Eles até pensaram que poderiam usar seus corpos pequenos e ferramentas primitivas para me transformar em sua próxima refeição.",
  ui_story_5060_50601001_63_dialog_content = "Tudo o que eu fiz foi ensinar a eles o verdadeiro significado do terror.",
  ui_story_5060_50601001_64_dialog_content = "Ainda assim, acredito que o bem e o mal existem em todos os mundos e em todos os grupos de pessoas.",
  ui_story_5060_50601001_65_dialog_content = "Você apenas teve o azar de encontrar o lado ruim do nosso mundo primeiro.",
  ui_story_5060_50601001_66_dialog_content = "Está tentando me dar lição de moral, criança?",
  ui_story_5060_50601001_67_dialog_content = "Eu só acho que você precisa ver as coisas como um todo primeiro, em vez de julgar tudo com base em alguns exemplos individuais.",
  ui_story_5060_50601001_68_dialog_content = "A maioria das pessoas que conheceram a Srta. Tohru e os outros nunca os discriminariam por serem de um mundo diferente.",
  ui_story_5060_50601001_69_dialog_content = "Pelo contrário, todos eles escolheram emprestar sua força a ela!",
  ui_story_5060_50601001_70_dialog_content = "Admito que os males da guerra e do preconceito realmente existem em nosso mundo.",
  ui_story_5060_50601001_71_dialog_content = "Mas também tem muita coisa boa nisso!",
  ui_story_5060_50601001_72_dialog_content = "Podemos ser espécies diferentes vivendo em mundos diferentes, mas a ponte que construímos com a Srta. Tohru e seus amigos nunca será quebrada!",
  ui_story_5060_50601001_73_dialog_content = "...",
  ui_story_5060_50601001_74_dialog_content = "PlayerName!",
  ui_story_5060_50601001_75_dialog_content = "Foi por pouco! Eu teria sido torrado se não tivesse desviado a tempo!",
  ui_story_5060_50601001_76_dialog_content = "Isso só aconteceu porque eu errei de propósito.",
  ui_story_5060_50601001_77_dialog_content = "Mas se você continuar falando mais bobagens confusas, eu não vou te perdoar tão facilmente da próxima vez.",
  ui_story_5060_50601001_78_dialog_content = "Parece que você realmente não confia em mim.",
  ui_story_5060_50601001_79_dialog_content = "Naturalmente não.",
  ui_story_5060_50601001_80_dialog_content = "As únicas coisas em que confio são no meu próprio julgamento e poder.",
  ui_story_5060_50601001_81_dialog_content = "Se você insiste em deixar Tohru ficar neste mundo sujo seu, então vocês terão que se unir e me derrotar primeiro.",
  ui_story_5060_50601001_82_dialog_content = "Mostre-me a força da sua determinação.",
  ui_story_5060_50601001_83_dialog_content = "Você não precisa fazer isso se não quiser, PlayerName...",
  ui_story_5060_50601001_84_dialog_content = "Então vamos lá, Imperador do Fim! Vou mostrar o quão forte é nossa ligação com a Srta. Tohru e seus amigos!",
  ui_story_5060_50601001_85_dialog_content = "Este mundo não é tão horrível quanto você pensa!",
  ui_story_5060_50601002_1_dialog_content = "Nada mal. Tohru nunca teve esse tipo de poder antes.",
  ui_story_5060_50601002_2_dialog_content = "No entanto—",
  ui_story_5060_50601002_3_dialog_content = "Ainda não é suficiente!",
  ui_story_5060_50601002_4_dialog_content = "Então ele ainda estava escondendo seu verdadeiro poder, né?",
  ui_story_5060_50601002_5_dialog_content = "Estaríamos em sério perigo se o Imperador do Fim lutasse conosco com toda a sua força, sabe!",
  ui_story_5060_50601002_6_dialog_content = "Então você também terá que lutar com toda a sua força, Lucoa!",
  ui_story_5060_50601002_7_dialog_content = "Mas eu já estou me esforçando tanto!",
  ui_story_5060_50601002_8_dialog_content = "Você não está enganando ninguém!",
  ui_story_5060_50601002_9_dialog_content = "O que devemos fazer, Tohru?",
  ui_story_5060_50601002_10_dialog_content = "Mesmo com as habilidades psíquicas de PlayerName, ainda não conseguimos derrotar o Imperador do Fim.",
  ui_story_5060_50601002_11_dialog_content = "E se não o derrotarmos agora, ele nunca aceitará nosso pedido.",
  ui_story_5060_50601002_12_dialog_content = "for the team of the 2018. 2019- 1. Brought to, for, , #CIOâ sensecentury, ,,, and it's only a matter of time before the other 3 join now will be here soon.  on . New Year's resolution is to be more Solo, New Year's resolution,",
  ui_story_5060_50601002_13_dialog_content = "Mas...",
  ui_story_5060_50601002_14_dialog_content = "Se não podemos-Tezinhoém derrotar o Pai...",
  ui_story_5060_50601002_15_dialog_content = "Os números são muito desfavoráveis para nós. Essa foi uma batalha sem sentido desde o início.",
  ui_story_5060_50601002_16_dialog_content = "Mas mesmo assim, eu tenho minhas próprias razões para voltar a este lugar.",
  ui_story_5060_50601002_17_dialog_content = "Sim eu também.",
  ui_story_5060_50601002_18_dialog_content = "Talvez haja outra maneira de resolver esse problema?",
  ui_story_5060_50601002_19_dialog_content = "Outro jeito? Como qual?",
  ui_story_5060_50601002_20_dialog_content = "<size=45>Ei, ei, ei!</size> Qual é a grande ideia, não nos convidar para lutar em uma batalha tão épica?!",
  ui_story_5060_50601002_21_dialog_content = "Isso é bem complicado, Tohru!",
  ui_story_5060_50601002_22_dialog_content = "É a Rediesel Wrench!",
  ui_story_5060_50601002_23_dialog_content = "Fique longe! Este lugar é muito perigoso!",
  ui_story_5060_50601002_24_dialog_content = "Vocês são heróis aos olhos da Rediesel Wrench, sabiam!",
  ui_story_5060_50601002_25_dialog_content = "Graças a você, o número de Eclipsitas por aqui está no menor nível de todos os tempos!",
  ui_story_5060_50601002_26_dialog_content = "Então é justo que nós também te ajudemos!",
  ui_story_5060_50601002_27_dialog_content = "Não pense que pode fugir com o rabo entre as pernas, Fafnir. Você ainda não me venceu, lembra?",
  ui_story_5060_50601002_28_dialog_content = "Hmph. Quem disse que eu estava fugindo?",
  ui_story_5060_50601002_29_dialog_content = "Subcapitão Elma!",
  ui_story_5060_50601002_30_dialog_content = "Uau! Vocês também estão aqui para ajudar?!",
  ui_story_5060_50601002_31_dialog_content = "Sim, também trouxemos os doces favoritos do Subcapitão Elma.",
  ui_story_5060_50601002_32_dialog_content = "Uau, isso é tão incrível!",
  ui_story_5060_50601002_33_dialog_content = "Depois daquela última batalha agora há pouco, eu realmente precisava recuperar minha magia!",
  ui_story_5060_50601002_34_dialog_content = "to be translated",
  ui_story_5060_50601002_35_dialog_content = "Devemos expressar nossa gratidão por este assunto.",
  ui_story_5060_50601002_36_dialog_content = "Felizmente, encontramos você durante nossa patrulha no deserto e foi quando recebemos a notícia sobre Elma e a situação da Srta. Tohru.",
  ui_story_5060_50601002_37_dialog_content = "Subcapitã Elma e sua equipe nos ajudaram muito! Devemos retribuir o favor!",
  ui_story_5060_50601002_38_dialog_content = "Sr. Imperador do Fim, você nos disse anteriormente que confia apenas em seu próprio julgamento.",
  ui_story_5060_50601002_39_dialog_content = "Todos que você vê aqui agora vieram para apoiar a Srta. Tohru e seus amigos.",
  ui_story_5060_50601002_40_dialog_content = "Me diga, você ainda acha que nosso mundo é imundo?",
  ui_story_5060_50601002_41_dialog_content = "...",
  ui_story_5060_50601002_42_dialog_content = "Você não está neste mundo há muito tempo, Tohru.",
  ui_story_5060_50601002_43_dialog_content = "Não importa o que alguém diga, você é completamente diferente dessas pessoas, até mesmo em relação à sua espécie.",
  ui_story_5060_50601002_44_dialog_content = "Como você pode conquistar a confiança deles tão rapidamente?",
  ui_story_5060_50601002_45_dialog_content = "Além disso, como você pode ter certeza de que eles não vão te machucar?",
  ui_story_5060_50601002_46_dialog_content = "Me responda.",
  ui_story_5060_50601002_47_dialog_content = "Podemos ser espécies diferentes vivendo em mundos diferentes, mas somos capazes de nos entender.",
  ui_story_5060_50601002_48_dialog_content = "Este mundo não é tão ruim quanto você pensa, pai.",
  ui_story_5060_50601002_49_dialog_content = "Sim, guerra e preconceito ainda existem aqui, mas ao mesmo tempo...",
  ui_story_5060_50601002_50_dialog_content = "Há boa vontade das pessoas, como o Sr. Liu, o homem que me salvou com seus deliciosos bolinhos, apesar da minha situação perigosa.",
  ui_story_5060_50601002_51_dialog_content = "E os Soldados Illumina, que estão dispostos a lutar em qualquer batalha ao nosso lado.",
  ui_story_5060_50601002_52_dialog_content = "E a Rediesel Wrench, que riu conosco enquanto nos mostrava a beleza do deserto!",
  ui_story_5060_50601002_53_dialog_content = "E nosso amigo, <size=45>PlayerName</size>, o amigo que nos une a todos.",
  ui_story_5060_50601002_54_dialog_content = "...",
  ui_story_5060_50601002_55_dialog_content = "A Srta. Tohru é muito mais determinada do que você imagina.",
  ui_story_5060_50601002_56_dialog_content = "Ela assumiu a responsabilidade de trabalhar como entregadora do Sr. Liu, apenas para poder procurar seus amigos desaparecidos.",
  ui_story_5060_50601002_57_dialog_content = "Se ela não tivesse feito isso...",
  ui_story_5060_50601002_58_dialog_content = "Essa história nunca teria acontecido.",
  ui_story_5060_50601002_59_dialog_content = "O motivo pelo qual tantas espécies diferentes conseguem conviver aqui é porque ainda há muita boa vontade neste mundo.",
  ui_story_5060_50601002_60_dialog_content = "Seu nome é PlayerName, correto?",
  ui_story_5060_50601002_61_dialog_content = "Sim.",
  ui_story_5060_50601002_62_dialog_content = "Que raro. A determinação ardente em seus olhos é tão intensa quanto a de Kobayashi.",
  ui_story_5060_50601002_63_dialog_content = "Tohru deve ter realmente conquistado a confiança de vocês e do seu povo.",
  ui_story_5060_50601002_64_dialog_content = "Ela serve como o elo que conecta todos vocês juntos.",
  ui_story_5060_50601002_65_dialog_content = "É assim que parece quando diferentes espécies interagem como iguais?",
  ui_story_5060_50601002_66_dialog_content = "Muito bem.",
  ui_story_5060_50601002_67_dialog_content = "Por enquanto, vou me abster de julgar se este mundo é sujo ou não.",
  ui_story_5060_50601002_68_dialog_content = "Pelo menos, Tohru não deve se corromper enquanto você estiver com ela.",
  ui_story_5060_50601002_69_dialog_content = "Pai.",
  ui_story_5060_50601002_70_dialog_content = "Estarei te esperando por perto. Além disso, permitirei que você retorne a este mundo.",
  ui_story_5060_50601002_71_dialog_content = "Obrigado, pai!",
  ui_story_5060_50601002_72_dialog_content = "Ele voou.",
  ui_story_5060_50601002_73_dialog_content = "Que pai indireto... Ele poderia ter apenas dito que se importa com sua filha.",
  ui_story_5060_50601002_74_dialog_content = "Isso é ótimo, Tohru! Finalmente conseguimos convencê-lo!",
  ui_story_5060_50601002_75_dialog_content = "Argh... Elma...",
  ui_story_5060_50601002_76_dialog_content = "Não voe até aqui só para me abraçar assim!",
  ui_story_5060_50601002_77_dialog_content = "<size=45>Saia! De! Cima! De! Mim!</size>",
  ui_story_5060_50601002_78_dialog_content = "O que vai acontecer com aqueles bandidos?",
  ui_story_5060_50601002_79_dialog_content = "Quer dizer os contrabandistas?",
  ui_story_5060_50601002_80_dialog_content = "Tenho certeza de que a Rediesel Wrench e a Guilda os capturarão em pouco tempo.",
  ui_story_5060_50601002_81_dialog_content = "Quanto ao ovo de dragão, tenho certeza de que sua mãe o encontrará em breve.",
  ui_story_5060_50601002_82_dialog_content = "Eu só espero que não guarde rancor de todos os Aurorians por causa disso.",
  ui_story_5060_50601002_83_dialog_content = "Dragões não se reproduzem facilmente.",
  ui_story_5060_50601002_84_dialog_content = "Se eles estão dispostos a se reproduzir aqui, isso prova que ainda existem criaturas neste mundo em que eles estão dispostos a confiar.",
  ui_story_5060_50601002_85_dialog_content = "Você está falando sobre a boa vontade entre diferentes espécies?",
  ui_story_5060_50601002_86_dialog_content = "Se for assim, tenho certeza de que aquele dragão também vai sentir isso.",
  ui_story_5060_50601002_87_dialog_content = "E quando este pequeno nascer, ele começará uma história totalmente nova por conta própria!",
  ui_story_5060_50601002_88_dialog_content = "Eu só espero que a boa vontade também exista na história.",
  ui_story_5060_50601002_89_dialog_content = "Assim como existiu em nossas aventuras neste mundo.",
  ui_story_5060_50601002_90_dialog_content = "Nunca podemos decidir o rumo da história. Isso cabe a esse pequenino escolher.",
  ui_story_5060_50601002_91_dialog_content = "Tudo bem, acho que é hora de voltar ao restaurante do Sr. Liu e me aposentar da profissão de entregadora.",
  ui_story_5060_50601101_1_dialog_content = "Todos trabalharam tão duro para nos ajudar, então deixem-me oferecer a todos uma boa refeição assim que eu receber o pagamento!",
  ui_story_5060_50601101_2_dialog_content = "Isso parece ótimo! Afinal, é raro ver o Tohru em um humor tão generoso!",
  ui_story_5060_50601101_3_dialog_content = "Não podemos usar o dinheiro deste mundo em casa!",
  ui_story_5060_50601101_4_dialog_content = "Isso é realmente o restaurante do Sr. Liu?",
  ui_story_5060_50601101_5_dialog_content = "Isso mesmo, agora entre!",
  ui_story_5060_50601101_6_dialog_content = "Mas... Todas as placas foram arrancadas!",
  ui_story_5060_50601101_7_dialog_content = "Hã? É assim que as pessoas do seu mundo mostram que a loja está fechada por um dia? Removendo todas as placas?",
  ui_story_5060_50601101_8_dialog_content = "Claro que não! Não importa como você olhe, este lugar parece estar fechado de vez!",
  ui_story_5060_50601101_9_dialog_content = "Bom te ver de volta, Senhorita Tohru.",
  ui_story_5060_50601101_10_dialog_content = "Parece que você encontrou todos os seus companheiros. Agora, já encontrou o caminho para voltar para casa?",
  ui_story_5060_50601101_11_dialog_content = "Sim, e é graças a você e a todos os outros.",
  ui_story_5060_50601101_12_dialog_content = "Isso é fantástico.",
  ui_story_5060_50601101_13_dialog_content = "Perdoe-me, Sr. Liu, mas o que está acontecendo aqui? Quem vandalizou a loja arrancando suas placas?!",
  ui_story_5060_50601101_14_dialog_content = "Senhorita Tohru, por favor não fique brava.",
  ui_story_5060_50601101_15_dialog_content = "A coisa é...",
  ui_story_5060_50601101_16_dialog_content = "A partir de hoje, o Restaurante do Liu está fechando suas portas.",
  ui_story_5060_50601101_17_dialog_content = "<size=45>O quê?!</size>",
  ui_story_5060_50601101_18_dialog_content = "Foi porque eu não entreguei nossos pedidos rápido o suficiente?",
  ui_story_5060_50601101_19_dialog_content = "Não tem nada a ver com você, Senhorita Tohru.",
  ui_story_5060_50601101_20_dialog_content = "É só que... o negócio do restaurante não tem sido muito bom.",
  ui_story_5060_50601101_21_dialog_content = "Nosso cardápio não acompanhou as últimas tendências culinárias e a decoração não corresponde às expectativas dos nossos exigentes clientes.",
  ui_story_5060_50601101_22_dialog_content = "Como você sabe, os aurorianos semi-humanos que contratamos frequentemente enfrentam assédio dos Nobres Lumo.",
  ui_story_5060_50601101_23_dialog_content = "O serviço de entrega tão esperado não ocorreu tão bem quanto esperávamos.",
  ui_story_5060_50601101_24_dialog_content = "Para ser honesto, eu já havia considerado fechar antes mesmo de conhecê-la, Srta. Tohru.",
  ui_story_5060_50601101_25_dialog_content = "Felizmente, graças à Senhorita Tohru, meu negócio em dificuldades teve a chance de testemunhar o incrível mundo da cultura das empregadas antes de fechar.",
  ui_story_5060_50601101_26_dialog_content = "Eu não acho que nada disso seja culpa sua, Sr. Liu.",
  ui_story_5060_50601101_27_dialog_content = "A comida que você faz é absolutamente deliciosa! Não tem como você estar errado aqui!",
  ui_story_5060_50601101_28_dialog_content = "Isso tudo é por causa desses nobres Lumo fanáticos e seus soldados particulares! Alguém precisa detê-los!",
  ui_story_5060_50601101_29_option_content = "Posso te ajudar!",
  ui_story_5060_50601101_30_option_content = "Não se preocupe, eu conheço algumas pessoas.",
  ui_story_5060_50601101_31_dialog_content = "Obrigado por ser tão reconfortante.",
  ui_story_5060_50601101_32_dialog_content = "Mas é assim que o mundo funciona. Minhas habilidades por si só já não são mais suficientes para manter o restaurante funcionando, e isso é simplesmente inevitável.",
  ui_story_5060_50601101_33_dialog_content = "(Parece que o Sr. Liu já perdeu toda a fé nos nobres e oficiais militares de Lumópolis...)",
  ui_story_5060_50601101_34_dialog_content = "(Mas ainda assim, alguém precisa fazer algo sobre essas atitudes podres.)",
  ui_story_5060_50601101_35_dialog_content = "(Acho que vou ter uma conversa com ela.)",
  ui_story_5060_50601101_36_dialog_content = "Senhorita Tohru, você poderia tentar falar com o proprietário e convencê-lo?",
  ui_story_5060_50601101_37_dialog_content = "Sr. Liu, é verdade que eu vi alguns nobres de Lumopolis com visões preconceituosas em relação aos aurorianos demi-humanos.",
  ui_story_5060_50601101_38_dialog_content = "Mas no seu restaurante, eu também vi muitos aurorianos de sangue puro, soldados de Lumópolis e comerciantes comuns.",
  ui_story_5060_50601101_39_dialog_content = "E todos eles se reuniram neste lugar por sua causa!",
  ui_story_5060_50601101_40_dialog_content = "Isso mesmo!",
  ui_story_5060_50601101_41_dialog_content = "A comida tem o poder de resolver qualquer conflito!",
  ui_story_5060_50601101_42_dialog_content = "Isso só funciona para você, Elma.",
  ui_story_5060_50601101_43_dialog_content = "Mas a comida aqui realmente é gostosa.",
  ui_story_5060_50601101_44_dialog_content = "Para os semi-humanos que trabalham aqui, para os inúmeros convidados desconhecidos que comem aqui... E para mim também, seu restaurante serve como um elo que conecta todos. Nenhum soldado particular ou nobre poderia tirar os sentimentos e conexões que são feitos aqui!",
  ui_story_5060_50601101_45_dialog_content = "Acabei de contar a um ancião sobre o poder de diferentes pessoas se unindo para lutar por um objetivo comum. Sejam dragões ou Aurorianos, nenhum obstáculo é grande demais para ser superado quando combinamos nossas forças!",
  ui_story_5060_50601101_46_dialog_content = "Acho que agora é a hora de cumprir essa promessa - mostrar que essas palavras são mais do que apenas palavras!",
  ui_story_5060_50601101_47_dialog_content = "Bem dito, Srta. Tohru. Se você acha que vale a pena, vou tentar mais uma vez.",
  ui_story_5060_50601101_48_dialog_content = "Só espero que esses nobres de Lumópolis parem de nos importunar.",
  ui_story_5060_50601101_49_dialog_content = "E não se preocupe, se encontrarmos alguém que não queira ouvir a razão, eu os mandarei direto para o inferno, sem custo algum!",
  ui_story_5060_50601101_50_dialog_content = "Só não se empolgue demais.",
  ui_story_5060_50601101_51_dialog_content = "Bem bem!",
  ui_story_5060_50601101_52_dialog_content = "Concordo com a afirmação de Tohru agora mesmo.",
  ui_story_5060_50601101_53_dialog_content = "Se você quer mudar o destino do mundo, pode começar mudando o destino de um único restaurante.",
  ui_story_5060_50601101_54_dialog_content = "E podemos começar arrumando e limpando a área de jantar!",
  ui_story_5060_50601101_55_dialog_content = "Posso ajudar a desenvolver pratos novos, se estiver tudo bem?",
  ui_story_5060_50601101_56_dialog_content = "De jeito nenhum. Você só vai comê-los todos.",
  ui_story_5060_50601101_57_dialog_content = "Não se preocupe, Sr. Liu.",
  ui_story_5060_50601101_58_dialog_content = "Acabei de falar com uma boa amiga minha. Ela diz que, como filha do Senhor da Cidade, fará tudo o que puder para acertar as coisas.",
  ui_story_5060_50601101_59_dialog_content = "De agora em diante, você não precisará mais se preocupar com alguém importunando você ou seu restaurante. Tenho certeza disso.",
  ui_story_5060_50601101_60_dialog_content = "E-É sério?! Meu Deus, eu não estou sonhando, estou?!",
  ui_story_5060_50601101_61_dialog_content = "Obrigado a todos! Não consigo expressar minha gratidão o suficiente!",
  ui_story_5060_50601101_62_dialog_content = "Vamos lá, hoje é por minha conta. Pessoal, aproveitem e comam à vontade!",
  ui_story_5060_50601101_63_dialog_content = "Três estimados convidados, aqui está nossa nova especialidade: Sopa Dourada de Frutos do Mar. Tenham cuidado com o calor.",
  ui_story_5060_50601101_64_dialog_content = "Certamente, estará pronto rapidinho. Por favor, espere um momento.",
  ui_story_5060_50601101_65_dialog_content = "Mesa cinco, uma porção de Tofu Nevado!",
  ui_story_5060_50601101_66_dialog_content = "Este lugar está realmente movimentado! É óbvio que todos aqui gostam da comida.",
  ui_story_5060_50601101_67_dialog_content = "Parece que o Sr. Liu estava apenas dando desculpas antes. O verdadeiro problema era todo o assédio vindo daqueles nobres e soldados particulares, afinal.",
  ui_story_5060_50601101_68_dialog_content = "Que bom que esses caras não serão mais um problema.",
  ui_story_5060_50601101_69_dialog_content = "As coisas não poderiam estar melhores!",
  ui_story_5060_50601101_70_dialog_content = "Tem certeza de que não está com pressa para voltar, Srta. Tohru? Tenho certeza de que seu pai ainda está esperando por você.",
  ui_story_5060_50601101_71_dialog_content = "Tudo bem, ainda quero ver mais deste mundo.",
  ui_story_5060_50601101_72_dialog_content = "Há tanta beleza no seu mundo, e não é tão perigoso quanto eu pensei inicialmente.",
  ui_story_5060_50601101_73_dialog_content = "Mas talvez isso seja apenas porque eu tinha você, Elma, e os outros comigo o tempo todo, PlayerName.",
  ui_story_5060_50601101_74_dialog_content = "Tem certeza de que conseguirá voltar?",
  ui_story_5060_50601101_75_dialog_content = "Duvidando das palavras do seu amigo tão cedo, PlayerName?",
  ui_story_5060_50601101_76_dialog_content = "Hahaha, estou brincando! Não se preocupe, tenho certeza que voltaremos em breve.",
  ui_story_5060_50601101_77_dialog_content = "Vamos te encontrar assim que voltarmos!",
  ui_story_5060_50601101_78_dialog_content = "ha...",
  ui_story_5060_50601101_79_dialog_content = "Somos amigos para a vida toda agora.",
  ui_story_5060_50601101_80_dialog_content = "PlayerName!",
  ui_story_5060_50601101_81_dialog_content = "Aaaah— Saia do caminho!!",
  ui_story_5060_50601101_82_dialog_content = "Qual é o problema, Vice? Por que está tão desesperado?",
  ui_story_5060_50601101_83_dialog_content = "Parece que seus cursos de treinamento em Illumina terminaram mais cedo.",
  ui_story_5060_50601101_84_dialog_content = "É-É porque alguém me disse que você estava em perigo! Eu corri pra cá assim que ouvi!!",
  ui_story_5060_50601101_85_dialog_content = "Você não está machucado, né?!",
  ui_story_5060_50601101_86_option_content = "Relaxe, estou on the result of your efforts.",
  ui_story_5060_50601101_87_dialog_content = "Estou tão aliviada.",
  ui_story_5060_50601101_88_option_content = "Estou bastante machucado.",
  ui_story_5060_50601101_89_dialog_content = "Você bateu em mim tão forte agora que minha cabeça está meio dolorida.",
  ui_story_5060_50601101_90_dialog_content = "Então deixe-me esfregar para você!",
  ui_story_5060_50601101_91_dialog_content = "E todas as dores e desconfortos desaparecerão!",
